const LIB_SRC = "// ===== MOTION ATLAS 코어 =====\n// 모든 데모는 「시간 t(초)의 순수한 함수」로 그린다(seek(t) 방식).\n// 같은 t라면 반드시 같은 그림이 되므로 일시정지·컷 전진·어니언 스킨을 그대로 쓸 수 있다.\nconst TAU = Math.PI * 2;\nconst clamp = (v, a = 0, b = 1) => v < a ? a : v > b ? b : v;\nconst lerp = (a, b, t) => a + (b - a) * t;\nconst fract = x => x - Math.floor(x);\nconst W = 320, H = 200;   // 데모 논리 크기(16:10)\n\n// ---- cubic-bezier(CSS와 같은 정의) ----\nfunction bez(x1, y1, x2, y2) {\n  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx, cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;\n  const sx = t => ((ax * t + bx) * t + cx) * t, sy = t => ((ay * t + by) * t + cy) * t, dx = t => (3 * ax * t + 2 * bx) * t + cx;\n  const f = x => {\n    if (x <= 0) return 0; if (x >= 1) return 1;\n    let t = x;\n    for (let i = 0; i < 8; i++) { const e = sx(t) - x, d = dx(t); if (Math.abs(e) < 1e-6 || Math.abs(d) < 1e-6) break; t -= e / d; }\n    if (Math.abs(sx(t) - x) > 1e-4) { let a = 0, b = 1; t = x; for (let i = 0; i < 40; i++) { if (sx(t) < x) a = t; else b = t; t = (a + b) / 2; } }\n    return sy(t);\n  };\n  f.b = [x1, y1, x2, y2]; return f;\n}\nconst bounceOut = x => { const n = 7.5625, d = 2.75; if (x < 1 / d) return n * x * x; if (x < 2 / d) return n * (x -= 1.5 / d) * x + .75; if (x < 2.5 / d) return n * (x -= 2.25 / d) * x + .9375; return n * (x -= 2.625 / d) * x + .984375; };\nconst E = {\n  linear: x => x,\n  inQuad: x => x * x, outQuad: x => 1 - (1 - x) * (1 - x), inOutQuad: x => x < .5 ? 2 * x * x : 1 - (-2 * x + 2) ** 2 / 2,\n  inCubic: x => x ** 3, outCubic: x => 1 - (1 - x) ** 3, inOutCubic: x => x < .5 ? 4 * x ** 3 : 1 - (-2 * x + 2) ** 3 / 2,\n  outQuart: x => 1 - (1 - x) ** 4, outQuint: x => 1 - (1 - x) ** 5,\n  inSine: x => 1 - Math.cos(x * Math.PI / 2), outSine: x => Math.sin(x * Math.PI / 2), sine: x => -(Math.cos(Math.PI * x) - 1) / 2,\n  outCirc: x => Math.sqrt(1 - (x - 1) ** 2),\n  smooth: x => x * x * (3 - 2 * x),\n  outExpo: bez(.16, 1, .3, 1), inExpo: bez(.7, 0, .84, 0), inOut: bez(.65, 0, .35, 1),\n  house: bez(.83, 0, .17, 1), whip: bez(.9, 0, .1, 1), glide: bez(.4, 0, .2, 1),\n  outBack: bez(.34, 1.56, .64, 1), inBack: bez(.36, 0, .66, -.56), inOutBack: bez(.68, -.6, .32, 1.6),\n  quint: bez(.22, 1, .36, 1), md3: bez(.2, 0, 0, 1), md3Emph: bez(.05, .7, .1, 1), md3Acc: bez(.3, 0, 1, 1), apple: bez(.25, .1, .25, 1),\n  elastic: x => x <= 0 ? 0 : x >= 1 ? 1 : 2 ** (-10 * x) * Math.sin((x * 10 - .75) * TAU / 3) + 1,\n  bounce: bounceOut,\n  steps: n => x => Math.min(1, Math.floor(x * n + 1e-9) / (n - 1 || 1)),\n  backS: s => x => 1 + (s + 1) * (x - 1) ** 3 + s * (x - 1) ** 2,\n};\n// ---- 스프링(닫힌 식 = 매 컷 계산 없이도 임의 t의 값이 나옴) ----\n// stiffness k / damping c / mass m. 0 → 1로 향하는 스텝 응답.\nfunction spring(t, k = 170, c = 26, m = 1) {\n  if (t <= 0) return 0;\n  const w0 = Math.sqrt(k / m), z = c / (2 * Math.sqrt(k * m));\n  if (z < 1) { const wd = w0 * Math.sqrt(1 - z * z); return 1 - Math.exp(-z * w0 * t) * (Math.cos(wd * t) + (z * w0 / wd) * Math.sin(wd * t)); }\n  if (Math.abs(z - 1) < 1e-6) return 1 - Math.exp(-w0 * t) * (1 + w0 * t);\n  const s = Math.sqrt(z * z - 1), r1 = -w0 * (z - s), r2 = -w0 * (z + s), A = r2 / (r2 - r1), B = -r1 / (r2 - r1);\n  return 1 - (A * Math.exp(r1 * t) + B * Math.exp(r2 * t));\n}\n// ζ(감쇠비)와 ω(고유 각진동수)로 지정하는 버전(Barty-Bart / motion-launch-videos 방식)\nfunction springZW(t, w = 15, z = .84) { return spring(t, w * w, 2 * z * w, 1); }\n// 목표가 여러 번 바뀌는 값: 변화마다 스프링을 하나씩 더한다(중간에 전환해도 연속)\nfunction track(t, keys, k = 170, c = 26, m = 1) { let v = keys[0][1]; for (let i = 1; i < keys.length; i++) v += (keys[i][1] - keys[i - 1][1]) * spring(t - keys[i][0], k, c, m); return v; }\n// 스프링의 성질(오버슈트 %와 수렴 시간)을 수치로 구한다\nfunction springStats(k, c, m) { let peak = 0, settle = 0; for (let i = 1; i <= 600; i++) { const t = i / 200, v = spring(t, k, c, m); if (v > peak) peak = v; if (Math.abs(v - 1) > .01) settle = t; } return { over: Math.max(0, (peak - 1) * 100), settle }; }\n\n// ---- 구간·키 ----\nconst seg = (t, a, b, e = E.inOut) => e(clamp((t - a) / (b - a)));\nfunction kf(t, keys, e = E.inOut) { if (t <= keys[0][0]) return keys[0][1]; for (let i = 1; i < keys.length; i++) if (t < keys[i][0]) { const [t0, v0] = keys[i - 1], [t1, v1] = keys[i]; return lerp(v0, v1, e((t - t0) / (t1 - t0))); } return keys[keys.length - 1][1]; }\nconst ping = (t, dur) => { const p = fract(t / dur); return p < .5 ? p * 2 : 2 - p * 2; };\n// 의사 난수(Math.random은 쓰지 않음)\nfunction rng(s) { return () => { s |= 0; s = s + 0x6D2B79F5 | 0; let t = Math.imul(s ^ s >>> 15, 1 | s); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }\nconst hash = n => fract(Math.sin(n * 127.1 + 311.7) * 43758.5453);\nconst noise1 = (x, s = 0) => { const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f); return lerp(hash(i + s * 57.3), hash(i + 1 + s * 57.3), u); };\nconst noise2 = (x, y, s = 0) => { const i = Math.floor(x), j = Math.floor(y), fx = x - i, fy = y - j, ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy), h = (a, b) => hash(a * 15.7 + b * 47.3 + s * 91.1); return lerp(lerp(h(i, j), h(i + 1, j), ux), lerp(h(i, j + 1), h(i + 1, j + 1), ux), uy); };\nconst onTwos = (t, fps = 24) => Math.floor(t * fps / 2) * 2 / fps;\n\n// ---- 색(모션 레퍼런스의 진남색 스테이지용. 악센트는 카드마다 전환) ----\nconst K = {};\nconst PALETTES = {\n  base: { ink: '#e8ebf3', mute: '#6c778b', paper: '#0d1320', card: '#182133', grid: '#232d42', line: '#2c3850', green: '#35c892' },\n  purple: { red: '#7d64ff', blue: '#22bdd6', yel: '#f2c84b' },\n  cyan: { red: '#22bdd6', blue: '#7d64ff', yel: '#f2c84b' },\n  coral: { red: '#ff725e', blue: '#7d64ff', yel: '#f2c84b' },\n  yellow: { red: '#f2c84b', blue: '#7d64ff', yel: '#ff725e' }\n};\nfunction setPalette(accent = 'purple') { Object.assign(K, PALETTES.base, PALETTES[accent] || PALETTES.purple); }\nfunction readPalette() { setPalette('purple'); }\nsetPalette('purple');\nconst FONT = { d: 'Pretendard,system-ui,sans-serif', b: 'Pretendard,system-ui,sans-serif', m: 'ui-monospace,SFMono-Regular,Menlo,Consolas,monospace' };\n// 표시 언어(영어 표시에서는 캔버스 안 일본어 라벨을 사전으로 교체)\nlet LANG = 'ko';\nconst TRD = {};\nfunction TR(map) { Object.assign(TRD, map); }\nconst L = s => (LANG === 'en' && typeof s === 'string' && TRD[s] !== undefined) ? TRD[s] : s;\n// fill/stroke에 쓰는 「마지막으로 그린 색」과 언어를 그리기 밖에서 전환하기 위함\n// ---- 그리기 소도구 ----\nfunction rr(g, x, y, w, h, r, fill, stroke, lw = 1.5) { r = Math.max(0, Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2)); g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath(); if (fill) { g.fillStyle = fill; g.fill(); } if (stroke) { g.strokeStyle = stroke; g.lineWidth = lw; g.stroke(); } }\nfunction circ(g, x, y, r, fill, stroke, lw = 1.5) { g.beginPath(); g.arc(x, y, Math.max(0, r), 0, TAU); if (fill) { g.fillStyle = fill; g.fill(); } if (stroke) { g.strokeStyle = stroke; g.lineWidth = lw; g.stroke(); } }\nfunction ln(g, x1, y1, x2, y2, c, w = 1.5, dash) { g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.strokeStyle = c; g.lineWidth = w; if (dash) g.setLineDash(dash); g.stroke(); if (dash) g.setLineDash([]); }\nfunction tx(g, s, x, y, o = {}) { s = L(s); const fw = (o.f === 'd') ? 800 : (o.w || 700); g.font = `${fw} ${o.size || 16}px ${FONT[o.f || 'b']}`; g.textAlign = o.a || 'center'; g.textBaseline = o.bl || 'middle'; g.fillStyle = o.c || K.ink; g.fillText(s, x, y); }\nfunction alpha(g, a, fn) { const p = g.globalAlpha; g.globalAlpha = p * clamp(a); fn(); g.globalAlpha = p; }\nfunction xf(g, x, y, sx, sy, rot, fn) { g.save(); g.translate(x, y); if (rot) g.rotate(rot); g.scale(sx, sy); fn(); g.restore(); }\nfunction clip(g, x, y, w, h, fn) { g.save(); g.beginPath(); g.rect(x, y, w, h); g.clip(); fn(); g.restore(); }\nfunction floor(g, y = 168) { ln(g, 24, y, W - 24, y, K.mute, 1); }\nfunction label(g, s, x = 12, y = 14) { tx(g, s, x, y, { a: 'left', size: 10, w: 500, f: 'm', c: K.mute }); }\nfunction star(g, x, y, r1, r2, n, fill, rot = 0) { g.beginPath(); for (let i = 0; i < n * 2; i++) { const a = rot + i * Math.PI / n - Math.PI / 2, r = i % 2 ? r2 : r1; g.lineTo(x + Math.cos(a) * r, y + Math.sin(a) * r); } g.closePath(); g.fillStyle = fill; g.fill(); }\nfunction poly(g, pts, fill, stroke, lw = 1.5) { g.beginPath(); pts.forEach(([x, y], i) => i ? g.lineTo(x, y) : g.moveTo(x, y)); g.closePath(); if (fill) { g.fillStyle = fill; g.fill(); } if (stroke) { g.strokeStyle = stroke; g.lineWidth = lw; g.stroke(); } }\n// 형태의 윤곽을 N점으로 맞춘다(모프용)\nfunction shapePts(kind, cx, cy, r, n = 64) { const out = []; for (let i = 0; i < n; i++) { const a = i / n * TAU - Math.PI / 2; let rr2 = r;\n    if (kind === 'square') { const c = Math.cos(a), s = Math.sin(a); rr2 = r / Math.max(Math.abs(c), Math.abs(s)); }\n    else if (kind === 'star') { const k = (i / n * 10) % 2; rr2 = r * (k < 1 ? lerp(1, .45, k) : lerp(.45, 1, k - 1)); }\n    else if (kind === 'tri') { const seg3 = Math.PI * 2 / 3, aa = ((a + Math.PI / 2) % seg3 + seg3) % seg3 - seg3 / 2; rr2 = r * .5 / Math.cos(aa); }\n    else if (kind === 'heart') { const tt = i / n * TAU; out.push([cx + r * .06 * 16 * Math.sin(tt) ** 3, cy - r * .06 * (13 * Math.cos(tt) - 5 * Math.cos(2 * tt) - 2 * Math.cos(3 * tt) - Math.cos(4 * tt))]); continue; }\n    out.push([cx + Math.cos(a) * rr2, cy + Math.sin(a) * rr2]); } return out; }\nconst lerpPts = (a, b, t) => a.map((p, i) => [lerp(p[0], b[i][0], t), lerp(p[1], b[i][1], t)]);\n// UI용 작은 커서\nfunction cursor(g, x, y, press = 0) { xf(g, x, y, 1 - press * .15, 1 - press * .15, 0, () => { poly(g, [[0, 0], [0, 15], [4, 11], [7, 17], [9.5, 16], [6.5, 10], [11, 10]], K.ink, K.paper, 1.2); }); }\n";
const HELPERS = {"easeView":"function easeView(g, t, fn, o = {}) {\n  const gx = 22, gy = 30, gw = 124, gh = 128, Y = v => gy + gh - 22 - v * (gh - 44), X = x => gx + x * gw;\n  rr(g, gx, gy, gw, gh, 6, null, K.grid, 1);\n  ln(g, gx, Y(0), gx + gw, Y(0), K.grid, 1, [3, 3]); ln(g, gx, Y(1), gx + gw, Y(1), K.grid, 1, [3, 3]);\n  g.beginPath(); for (let i = 0; i <= 80; i++) { const x = i / 80; g.lineTo(X(x), Y(fn(x))); } g.strokeStyle = K.blue; g.lineWidth = 2; g.stroke();\n  const p = clamp((t - .3) / (o.d || 1.2)), v = fn(p);\n  ln(g, X(p), gy + 4, X(p), gy + gh - 4, K.mute, 1, [2, 3]); circ(g, X(p), Y(v), 4.5, K.red);\n  const a = 178, b = 292, ty = 74; ln(g, a, ty + 18, b, ty + 18, K.grid, 1);\n  rr(g, lerp(a, b, v) - 12, ty - 12, 24, 24, 5, K.red);\n  for (let i = 0; i <= 12; i++) { const x = lerp(a, b, fn(i / 12)); ln(g, x, 124, x, i % 6 ? 134 : 140, K.ink, 1.2); }\n  tx(g, '스페이싱(12컷)', (a + b) / 2, 152, { size: 9, w: 500, c: K.mute });\n  if (o.lab) label(g, o.lab);\n}","springView":"function springView(g, t, k, c, m, o = {}) {\n  const gx = 22, gy = 30, gw = 124, gh = 128, T = 1.6, Y = v => gy + gh - 22 - v * (gh - 50), X = s => gx + s / T * gw;\n  rr(g, gx, gy, gw, gh, 6, null, K.grid, 1); ln(g, gx, Y(1), gx + gw, Y(1), K.grid, 1, [3, 3]); ln(g, gx, Y(0), gx + gw, Y(0), K.grid, 1, [3, 3]);\n  g.beginPath(); for (let i = 0; i <= 90; i++) { const s = i / 90 * T; g.lineTo(X(s), Y(spring(s, k, c, m))); } g.strokeStyle = K.blue; g.lineWidth = 2; g.stroke();\n  const s = clamp(t - .3, 0, T), v = spring(s, k, c, m); circ(g, X(s), Y(v), 4.5, K.red);\n  const a = 178, b = 280, ty = 74; ln(g, b, ty - 20, b, ty + 20, K.grid, 1, [3, 3]);\n  rr(g, lerp(a, b, v) - 12, ty - 12, 24, 24, 5, K.red);\n  const st = springStats(k, c, m);\n  tx(g, `${L('오버슈트')} ${st.over.toFixed(1)}%`, 236, 128, { size: 10, w: 500, f: 'm', c: K.ink });\n  tx(g, `${L('수렴')} ${Math.round(st.settle * 1000)}ms`, 236, 146, { size: 10, w: 500, f: 'm', c: K.mute });\n  if (o.lab) label(g, o.lab);\n}","EASES":"const EASES = [\n  ['linear', 'linear(등속)', 'Linear', E.linear, '회전·표류·시계 바늘 같은 「시작도 끝도 없는」 움직임에만 쓴다.', ['linear'], ['whaley', 'iart']],\n  ['outexpo', 'ease-out expo(등장)', 'Ease-out Expo', E.outExpo, '순간에 튀어나와 오래 감속한다. 등장의 정석. 고민되면 이것.', ['cubic-bezier(.16,1,.3,1)', '300〜500ms'], ['whaley', 'iart', 'klik', 'haidr', 'remotion']],\n  ['inexpo', 'ease-in expo(퇴장)', 'Ease-in Expo', E.inExpo, '가속하며 떠난다. 퇴장은 등장의 65~75% 길이로.', ['cubic-bezier(.7,0,.84,0)', '200〜300ms'], ['iart', 'klik', 'haidr']],\n  ['inout', 'ease-in-out cubic(이동)', 'Ease-in-out Cubic', E.inOut, '화면 안 A에서 B로의 이동. 양 끝을 부드럽게.', ['cubic-bezier(.65,0,.35,1)', '300〜400ms'], ['whaley', 'iart']],\n  ['house', '신피크(하우스 커브)', 'Thin-peak (House curve)', E.house, '천천히 쌓아 올려 중앙에서 한 번에 몰고 부드럽게 착지. 단조로운 속도를 피하는 기본 커브.', ['cubic-bezier(.83,0,.17,1)'], ['klik', 'haidr']],\n  ['whip', 'WHIP(채찍)', 'Whip', E.whip, '거의 수직인 피크. 때려붙이기·트랜지션용. 빠른 구간에 스미어를 더한다.', ['cubic-bezier(.9,0,.1,1)'], ['klik']],\n  ['glide', 'GLIDE(글라이드)', 'Glide', E.glide, '머티리얼풍의 부드러운 커브. 글자 근처나 UI 설명용. 고급스러운 프리미엄 정석.', ['cubic-bezier(.4,0,.2,1)'], ['klik', 'lottie']],\n  ['quint', 'ease-out quint', 'Ease-out Quint', E.quint, 'Motion(motion.dev) 계열에서 자주 쓰는 등장 커브. 0.6~0.8초 등장용.', ['cubic-bezier(.22,1,.36,1)'], ['mdev', 'iart']],\n  ['md3', 'Material 3 표준', 'Material 3 Standard', E.md3, 'Material의 표준. 기업용·제품 UI의 기본값.', ['cubic-bezier(.2,0,0,1)'], ['iart', 'lottie']],\n  ['md3e', 'Material 3 강조(감속)', 'Material 3 Emphasized', E.md3Emph, '강조한 등장. 히어로의 볼거리에.', ['cubic-bezier(.05,.7,.1,1)'], ['lottie']],\n  ['md3a', 'Material 3 가속(퇴장)', 'Material 3 Accelerate', E.md3Acc, '퇴장용. 끝까지 가속하며 사라진다.', ['cubic-bezier(.3,0,1,1)'], ['lottie', 'iart']],\n  ['apple', 'Apple 표준', 'Apple HIG', E.apple, 'CSS의 ease와 같은 값. 기본값 그대로 쓰지 말고 의도해서 고른다.', ['cubic-bezier(.25,.1,.25,1)'], ['iart', 'lottie']],\n  ['outback', 'back out(오버슈트)', 'Back Out', E.outBack, '목표를 조금 넘었다 돌아온다. 장난기·성공 연출. UI에서는 쓸 곳을 좁힌다.', ['cubic-bezier(.34,1.56,.64,1)', '400〜600ms'], ['iart', 'launch', 'lottie']],\n  ['inback', 'back in(당겼다가 떠남)', 'Back In', E.inBack, '한 번 반대로 당긴 뒤 가속하며 퇴장. 퇴장의 예비 동작.', ['cubic-bezier(.36,0,.66,-.56)'], ['iart']],\n  ['inoutback', 'back in-out', 'Back In-out', E.inOutBack, '양 끝에서 오버슈트. 눈에 띄지만 많이 쓰지 않는다.', ['cubic-bezier(.68,-.6,.32,1.6)'], ['iart']],\n  ['sine', 'sine in-out(호흡)', 'Sine In-out', E.sine, '루프되는 표류·호흡용. 꿈꾸는 듯한 온화함.', ['sine.inOut'], ['lottie', 'student']],\n  ['circ', 'circ out', 'Circ Out', E.outCirc, '처음에 강하고 마지막에 갑자기 멈춘다. 기계적인 인상.', ['cubic-bezier(0,.55,.45,1)'], ['iart', 'gsap']],\n  ['elastic', 'elastic out(고무)', 'Elastic Out', E.elastic, '여러 번 흔들다 멈춘다. 장난기. 프리미엄에서는 쓰지 않는다.', ['elastic.out(1, 0.3)'], ['gsap', 'pdoom']],\n  ['bounce', 'bounce out(바운스)', 'Bounce Out', E.bounce, '바닥에서 튀듯 멈춘다. 낙하·착지 표현.', ['bounce.out'], ['gsap', 'mdev']],\n  ['steps', 'steps(컷 촬영)', 'Steps / Posterize', E.steps(6), '값을 단계적으로. 스톱모션·끊김풍.', ['steps(6)', 'posterize'], ['remotion', 'gsap']],\n  ['slowmo', 'SlowMo(빠름→느림→빠름)', 'SlowMo', bez(.1, .65, .9, .35), '중앙만 느리게. 매트릭스풍 슬로 연출(여기서는 근사 커브).', ['SlowMo.config(0.7, 0.7)'], ['gsap']],\n  ['rough', 'RoughEase(거친 떨림)', 'RoughEase', x => clamp(x + (noise1(x * 22, 3) - .5) * .18 * Math.sin(Math.PI * x), -.1, 1.1), '잘게 떨면서 나아간다. 노이즈·불안정함 표현.', ['rough({points:20, strength:1})'], ['gsap']],\n];","SPRINGS":"const SPRINGS = [\n  ['snap', 'snap(손가락으로 튕기기)', 'Snap', 180, 13, .6, 'UI 누름·작은 악센트. 경쾌하게.', ['damping 13 / stiffness 180 / mass 0.6'], ['klik']],\n  ['bounce', 'bounce(볼)', 'Bounce', 150, 9, .8, '두 번 또렷하게 튕긴다. 놀이·마스코트·보여줄 장면에만.', ['damping 9 / stiffness 150 / mass 0.8'], ['klik']],\n  ['smooth', 'smooth(댐퍼 달린 문)', 'Smooth', 120, 26, 1, '오버슈트 없음. 세련된 도착·본문 근처.', ['damping 26 / stiffness 120 / mass 1'], ['klik']],\n  ['heavy', 'heavy(무거운 물체)', 'Heavy', 80, 16, 1.6, '큰 카드·화면 가득한 물체. 천천히 착지.', ['damping 16 / stiffness 80 / mass 1.6'], ['klik']],\n  ['rsdefault', 'react-spring default', 'react-spring default', 170, 26, 1, 'tension 170 / friction 26. 고민될 때의 기준값.', ['tension 170 / friction 26'], ['iart', 'howseen']],\n  ['wobbly', 'react-spring wobbly', 'react-spring wobbly', 180, 12, 1, '쫄깃하게 흔들린다. 캐릭터·스티커용.', ['tension 180 / friction 12'], ['iart']],\n  ['molasses', 'react-spring molasses', 'react-spring molasses', 280, 120, 1, '시럽처럼 끈적하게. 과감쇠로 느리게.', ['tension 280 / friction 120'], ['iart']],\n  ['framerbouncy', 'Framer bouncy', 'Framer Motion bouncy', 400, 17, 1, '강하고 빠른 스프링+또렷한 반동.', ['stiffness 400 / damping 17'], ['iart', 'mdev']],\n  ['modal', 'Apple 모달', 'Apple modal', 280, 28, 1, '모달 표시 스프링. 살짝 넘어선 뒤 가라앉는다.', ['stiffness 280 / damping 28'], ['iart']],\n  ['critical', '임계 감쇠(흔들리지 않는 최속)', 'Critically damped', 300, 34.64, 1, '감쇠비 정확히 1. 넘지 않고 가장 빨리 멈춘다.', ['stiffness 300 / damping 34.6'], ['mdev', 'lottie']],\n];","staggerGrid":"function staggerGrid(g, t, order, lab) { const n = 8, m = 4; for (let j = 0; j < m; j++) for (let i = 0; i < n; i++) { const d = order(i, j, n, m), p = spring(t - .3 - d, 260, 20) * (1 - seg(t, 2.3, 2.6)); xf(g, 48 + i * 32, 52 + j * 32, p, p, 0, () => rr(g, -12, -12, 24, 24, 5, d === 0 ? K.red : K.ink)); } label(g, lab); }","_oc":"const _oc = document.createElement('canvas'); _oc.width = W * 2; _oc.height = H * 2;","offscreen":"function offscreen(fn) { const c = _oc.getContext('2d'); c.setTransform(2, 0, 0, 2, 0, 0); c.globalCompositeOperation = 'source-over'; c.globalAlpha = 1; c.clearRect(0, 0, W, H); fn(c); c.globalCompositeOperation = 'source-over'; return _oc; }","sceneA":"function sceneA(g) { rr(g, 0, 0, W, H, 0, K.card); circ(g, 110, 100, 46, K.ink); tx(g, 'A', 230, 100, { size: 64, f: 'd', w: 400, c: K.ink }); }","sceneB":"function sceneB(g) { rr(g, 0, 0, W, H, 0, K.red); rr(g, 170, 54, 92, 92, 10, K.paper); tx(g, 'B', 90, 100, { size: 64, f: 'd', w: 400, c: K.paper }); }","transView":"function transView(g, t, fn, dur = 3) { const h = dur / 2, first = t < h, p = first ? seg(t, h * .35, h * .85, E.linear) : seg(t, h + h * .35, h + h * .85, E.linear); fn(g, p, first ? sceneA : sceneB, first ? sceneB : sceneA); }","T":"const T = (id, ko, en, d, v, s, fn, extra = {}) => D({ id: 'tr-' + id, c: 'transitions', ko, en, d, v, s, dur: 3, kw: [en.split(' ')[0].toLowerCase(), 'transition'], src: `function f(g, t) { transView(g, t, ${fn.toString()}); }`, f(g, t) { transView(g, t, fn); }, ...extra });","world":"function world(g, cam = {}) {\n  const { x = 0, y = 0, z = 1, r = 0, dolly = 1, blurNear = 0, blurFar = 0, flat = false } = cam;\n  const layer = (depth, fn, bl = 0) => { const k = flat ? 1 : depth, s = flat ? z : 1 + (z - 1) * k * dolly; g.save(); if (bl > .2) g.filter = `blur(${bl}px)`; g.translate(W / 2, H / 2); g.rotate(r); g.scale(s, s); g.translate(-W / 2 - x * k, -H / 2 - y * k); fn(); g.restore(); };\n  rr(g, 0, 0, W, H, 0, K.paper);\n  layer(.2, () => { for (let i = -3; i < 9; i++) poly(g, [[i * 70 - 20, 150], [i * 70 + 25, 70 + (i % 3) * 14], [i * 70 + 70, 150]], K.grid); }, blurFar);\n  layer(.55, () => { for (let i = -3; i < 12; i++) rr(g, i * 46, 110 + (i % 2) * 8, 22, 60, 4, K.mute); });\n  layer(1, () => { rr(g, -200, 168, 800, 40, 0, K.ink); circ(g, 160, 128, 26, K.red); rr(g, 148, 150, 24, 18, 4, K.red); }, 0);\n  layer(1.6, () => { for (let i = -2; i < 8; i++) rr(g, i * 90 + 10, 150, 30, 70, 6, K.ink); }, blurNear);\n}","CAM":"const CAM = (id, ko, en, d, v, s, cam, dur = 3) => D({ id: 'cam-' + id, c: 'camera', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'camera'], src: `function f(g, t) { world(g, (${cam.toString()})(t)); }`, f(g, t) { world(g, cam(t)); } });","charsAt":"function charsAt(g, s, size, font = 'd', w = 400) { s = L(s); if (font === 'd') w = 800; g.font = `${w} ${size}px ${FONT[font]}`; const ws = [...s].map(c => g.measureText(c).width), tot = ws.reduce((a, b) => a + b, 0); let x = -tot / 2; return [...s].map((c, i) => { const cx = x + ws[i] / 2; x += ws[i]; return [c, cx, ws[i]]; }); }","drawChar":"function drawChar(g, c, x, y, size, col = K.ink, font = 'd', w = 400) { if (font === 'd') w = 800; g.font = `${w} ${size}px ${FONT[font]}`; g.textAlign = 'center'; g.textBaseline = 'alphabetic'; g.fillStyle = col; g.fillText(c, x, y); }","TY":"const TY = (id, ko, en, d, v, s, dur, f) => D({ id: 'ty-' + id, c: 'typography', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'type', 'text'], f });","U":"const U = (id, ko, en, d, v, s, dur, f, kw = []) => D({ id: 'ui-' + id, c: 'ui', ko, en, d, v, s, dur, kw: kw.concat([en.split(' ')[0].toLowerCase()]), f });","LD":"const LD = (id, ko, en, d, v, s, dur, f) => D({ id: 'ld-' + id, c: 'loaders', ko, en, d, v, s, dur, kw: ['loader', 'loading'], f });","SH":"const SH = (id, ko, en, d, v, s, dur, f) => D({ id: 'sh-' + id, c: 'shapes', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'svg', 'shape'], f });","PT":"const PT = (id, ko, en, d, v, s, dur, f) => D({ id: 'pt-' + id, c: 'particles', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'particle'], f });","LP":"const LP = (id, ko, en, d, v, s, dur, f) => D({ id: 'lp-' + id, c: 'loops', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'loop'], f });","DV":"const DV = (id, ko, en, d, v, s, dur, f) => D({ id: 'dv-' + id, c: 'data-viz', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'chart', 'data'], f });","CH":"const CH = (id, ko, en, d, v, s, dur, f) => D({ id: 'ch-' + id, c: 'character', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'character'], f });","blobby":"function blobby(g, x, y, sx = 1, sy = 1, eye = 1, mouth = 0) { xf(g, x, y, sx, sy, 0, () => { rr(g, -26, -52, 52, 52, 22, K.red); rr(g, -12, -36, 6, 10 * eye + .5, 3, K.paper); rr(g, 6, -36, 6, 10 * eye + .5, 3, K.paper); if (mouth) circ(g, 0, -16, 5 * mouth, K.paper); }); }","LK":"const LK = (id, ko, en, d, v, s, dur, f) => D({ id: 'lk-' + id, c: 'painterly', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'look', 'texture'], f });","sampleArt":"function sampleArt(g, t) { const x = 160 + Math.sin(t * 2) * 60; rr(g, 0, 0, W, H, 0, K.blue); circ(g, x, 90, 36, K.yel); rr(g, 40, 130, 240, 40, 8, K.ink); tx(g, 'LOOK', x, 92, { size: 18, f: 'd', w: 400, c: K.paper }); }","TD":"const TD = (id, ko, en, d, v, s, dur, f) => D({ id: '3d-' + id, c: '3d', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), '3d', 'perspective'], f });","proj":"const proj = (x, y, z, f = 360) => { const s = f / (f + z); return [160 + x * s, 100 + y * s, s]; };","SC":"const SC = (id, ko, en, d, v, s, dur, f, c = 'scroll') => D({ id: 'sc-' + id, c, ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'scroll'], f });","phone":"function phone(g, fn) { rr(g, 110, 8, 100, 184, 16, K.card, K.ink, 2); clip(g, 114, 12, 92, 176, fn); }","SD":"const SD = (id, ko, en, d, v, s, dur, f) => D({ id: 'sd-' + id, c: 'sound', ko, en, d, v, s, dur, kw: [en.split(' ')[0].toLowerCase(), 'sound', 'beat'], f });","b01InQuart":"const b01InQuart = x => x ** 4;","b01Quint":"const b01Quint = x => x < .5 ? 16 * x ** 5 : 1 - (-2 * x + 2) ** 5 / 2;","b01Q":"const b01Q = (u, a, c, b) => (1 - u) ** 2 * a + 2 * (1 - u) * u * c + u * u * b;","b01Dash":"function b01Dash(g, d, fn) { g.setLineDash(d); fn(); g.setLineDash([]); }","b01Num":"function b01Num(g, s, x, y, c, a) { tx(g, s, x, y, { size: 10, w: 500, f: 'm', c: c || K.ink, a: a || 'center' }); }","b01Blur":"function b01Blur(g, px, extra) { const b = px > .05 ? `blur(${(px * Math.abs(g.getTransform().a)).toFixed(2)}px)` : ''; g.filter = ((extra || '') + ' ' + b).trim() || 'none'; }","b01Card":"function b01Card(g, w, h) { const x = -w / 2, y = -h / 2; rr(g, x, y, w, h, 10, K.card, K.grid, 1); rr(g, x + 14, y + 14, w * .4, 10, 3, K.red); rr(g, x + 14, y + 34, w - 28, 7, 3.5, K.mute); rr(g, x + 14, y + 48, w * .55, 7, 3.5, K.mute); }","b01Keys":"function b01Keys(t, keys) {\n  if (t <= keys[0][0]) return keys[0][1];\n  for (let i = 1; i < keys.length; i++) if (t < keys[i][0]) { const [t0, v0] = keys[i - 1], [t1, v1, e = E.inOut] = keys[i]; return lerp(v0, v1, e((t - t0) / (t1 - t0))); }\n  return keys[keys.length - 1][1];\n}","b01Speed":"function b01Speed(g, dv, p, x, y, w, h) {\n  rr(g, x, y, w, h, 4, null, K.grid, 1);\n  const Y = v => y + h - 5 - v * (h - 12);\n  g.beginPath(); g.moveTo(x, Y(0)); for (let i = 0; i <= 60; i++) g.lineTo(x + i / 60 * w, Y(dv(i / 60))); g.lineTo(x + w, Y(0)); g.strokeStyle = K.blue; g.lineWidth = 1.5; g.stroke();\n  const live = p > 0 && p < 1; circ(g, x + p * w, Y(live ? dv(p) : 0), 3.2, K.red);\n  b01Num(g, 'speed', x + 4, y - 7, K.mute, 'left');\n}","b01IrisScene":"function b01IrisScene(g, fx, fy, fw, fh) {\n  rr(g, fx, fy, fw, fh, 10, K.card);\n  rr(g, fx + 14, fy + 14, 34, 6, 3, K.mute); rr(g, fx + fw - 48, fy + 14, 34, 6, 3, K.mute); rr(g, fx + 14, fy + fh - 20, 22, 6, 3, K.grid); rr(g, fx + fw - 36, fy + fh - 20, 22, 6, 3, K.grid);\n  circ(g, 160, 80, 26, K.red); circ(g, 160, 74, 9, K.paper);\n  g.save(); g.beginPath(); g.arc(160, 80, 26, 0, TAU); g.clip(); circ(g, 160, 102, 17, K.paper); g.restore();\n  rr(g, 125, 116, 70, 8, 4, K.ink); rr(g, 138, 130, 44, 6, 3, K.mute);\n}","b01P0":"const b01P0 = [56, 154], b01P1 = [160, 30], b01P2 = [264, 154];","b01Bz":"const b01Bz = u => [b01Q(u, b01P0[0], b01P1[0], b01P2[0]), b01Q(u, b01P0[1], b01P1[1], b01P2[1])];","b01Curve":"function b01Curve(g, u0, u1, c, w, dash) { g.beginPath(); for (let i = 0; i <= 50; i++) { const [x, y] = b01Bz(lerp(u0, u1, i / 50)); i ? g.lineTo(x, y) : g.moveTo(x, y); } g.strokeStyle = c; g.lineWidth = w; if (dash) g.setLineDash(dash); g.stroke(); g.setLineDash([]); }","b01ElKeys":"const b01ElKeys = [[0, .1], [.405, 1.2, E.outCubic], [.612, .92, E.sine], [.756, 1.06, E.sine], [.9, 1, E.sine]];","b01AxX":"const b01AxX = s => 60 + 200 * (E.inOutBack(seg(s, .3, 1.0, E.linear)) - E.inOutBack(seg(s, 1.55, 2.25, E.linear)));","b01Mini":"function b01Mini(g, x, y, hero) { rr(g, x - 32, y - 40, 64, 80, 8, K.card, K.grid, 1); rr(g, x - 22, y - 30, 26, 8, 3, hero ? K.red : K.mute); rr(g, x - 22, y - 14, 44, 6, 3, K.grid); rr(g, x - 22, y - 2, 32, 6, 3, K.grid); }","b01FoldP":"function b01FoldP(x, yl, a) { const z = yl * Math.sin(a), s = 420 / (420 + z), y = 48 + yl * Math.cos(a); return [160 + (x - 160) * s, 96 + (y - 96) * s]; }","b01FoldQ":"function b01FoldQ(g, x0, y0, x1, y1, a, fill, stroke) { poly(g, [b01FoldP(x0, y0, a), b01FoldP(x1, y0, a), b01FoldP(x1, y1, a), b01FoldP(x0, y1, a)], fill, stroke, 1); }","b01Zig":"const b01Zig = [[70, 100], [133, 68], [199, 128], [271, 100]];","b01ZigY":"const b01ZigY = x => { for (let i = 1; i < b01Zig.length; i++) if (x <= b01Zig[i][0]) return lerp(b01Zig[i - 1][1], b01Zig[i][1], (x - b01Zig[i - 1][0]) / (b01Zig[i][0] - b01Zig[i - 1][0])); return b01Zig[3][1]; };","b02Arrow":"function b02Arrow(g, fill = K.red) {\n  rr(g, -30, -30, 60, 60, 10, fill);\n  g.lineCap = 'round'; ln(g, -11, 11, 9, -9, K.paper, 5); g.lineCap = 'butt';\n  poly(g, [[15, -15], [-2, -15], [15, 2]], K.paper);\n}","b02ArrowGhost":"function b02ArrowGhost(g) { rr(g, -30, -30, 60, 60, 10, null, K.mute, 1); ln(g, -11, 11, 12, -12, K.mute, 1); }","b02Dash":"function b02Dash(g, fn, d = [3, 3]) { g.setLineDash(d); fn(); g.setLineDash([]); }","b02Slot":"function b02Slot(g, x, y, w, h, r = 6) { alpha(g, .55, () => b02Dash(g, () => rr(g, x, y, w, h, r, null, K.mute, 1))); }","b02Row":"function b02Row(g, x, y, w, h, i, thumb = false) {\n  rr(g, x, y, w, h, 6, K.card, K.grid, 1);\n  if (thumb) rr(g, x + 5, y + 4, h - 8, h - 8, 3, K.red); else circ(g, x + 14, y + h / 2, 5, K.red);\n  rr(g, x + (thumb ? h + 4 : 28), y + h / 2 - 3, [74, 98, 60, 86][i % 4], 6, 3, K.mute);\n  rr(g, x + w - 28, y + h / 2 - 3, 16, 6, 3, K.grid);\n}","b02Hop":"function b02Hop(u, H0, d0, peaks, durs) {\n  if (u <= 0) return H0;\n  if (u < d0) return H0 * (1 - (u / d0) ** 2);\n  let s = d0;\n  for (let i = 0; i < peaks.length; i++) { const d = durs[i]; if (u < s + d) { const v = (u - s) / d; return peaks[i] * 4 * v * (1 - v); } s += d; }\n  return 0;\n}","b02Contacts":"function b02Contacts(d0, durs) { const c = [d0]; let s = d0; durs.forEach(d => { s += d; c.push(s); }); return c; }","b02proj":"function b02proj(x, y, z, cx = 160, cy = 100, f = 360) { const s = f / (f + z); return [cx + x * s, cy + y * s, s]; }","b02Cell":"function b02Cell(r, c, size = 36, gap = 8, cx = 160, cy = 102) { const p = size + gap, o = p; return [cx + (c - 1) * o, cy + (r - 1) * o]; }","b02SpinE":"const b02SpinE = bez(.3, .45, .15, 1);","b02Tilt":"function b02Tilt(t, t0) {\n  const u = t - t0; if (u <= 0) return 0;\n  if (u < .12) return 16 * E.outCubic(u / .12);\n  if (u < .3) return lerp(16, -3, E.inOut((u - .12) / .18));\n  if (u < .48) return lerp(-3, 0, E.inOut((u - .3) / .18));\n  return 0;\n}","b02BodyX":"function b02BodyX(t) { return 70 + 180 * (seg(t, .2, 1.08, E.inOut) - seg(t, 2.0, 2.88, E.inOut)); }","b02Chain":"function b02Chain(t) {\n  const bx = b02BodyX(t), keys = [[0, 70]];\n  for (let j = 1; j <= 22; j++) { const tj = .2 + j * .88 / 22; keys.push([tj, b02BodyX(tj)]); }\n  for (let j = 1; j <= 22; j++) { const tj = 2.0 + j * .88 / 22; keys.push([tj, b02BodyX(tj)]); }\n  let px = bx, py = 128; const pts = [[px, py]];\n  for (let i = 0; i < 5; i++) { const k = 240 / (1 + i * .8), c = 2 * .26 * Math.sqrt(k), off = track(t, keys, k, c) - bx, ang = -Math.PI / 2 + clamp(off * .04, -1.15, 1.15); px += Math.cos(ang) * 10; py += Math.sin(ang) * 10; pts.push([px, py]); }\n  return pts;\n}","b03Rgb":"function b03Rgb(h) { h = String(h); if (h[0] !== '#') return (h.match(/[\\d.]+/g) || [0, 0, 0]).slice(0, 3).map(Number); const n = parseInt(h.slice(1), 16); return [n >> 16 & 255, n >> 8 & 255, n & 255]; }","b03A":"const b03A = (h, a) => { const c = b03Rgb(h); return `rgba(${c[0]},${c[1]},${c[2]},${clamp(a)})`; };","b03Mix":"const b03Mix = (h1, h2, k) => { const a = b03Rgb(h1), b = b03Rgb(h2); return `rgb(${a.map((v, i) => Math.round(lerp(v, b[i], clamp(k)))).join(',')})`; };","b03Bump":"const b03Bump = (t, a, b) => Math.sin(clamp((t - a) / (b - a)) * Math.PI);","b03Glow":"function b03Glow(g, blur, fn) { g.save(); g.shadowColor = K.red; g.shadowBlur = Math.min(18, Math.max(0, blur)); fn(); g.restore(); }","b03Step":"function b03Step(p, keys) { let v = keys[0][1]; for (const [k, val] of keys) if (p >= k) v = val; return v; }","b03Read":"function b03Read(g, s, x = 160, y = 186, c) { tx(g, s, x, y, { size: 10, f: 'm', w: 500, c: c || K.mute }); }","b03Meter":"function b03Meter(g, name, v, x, y, w, col) { tx(g, name, x - 8, y + 2, { a: 'right', size: 9, f: 'm', w: 500, c: K.mute }); rr(g, x, y - 1, w, 6, 3, K.grid); rr(g, x, y - 1, Math.max(6, w * clamp(v)), 6, 3, col || K.red); }","b03Picture":"function b03Picture(g, x, y, w, h, r = 10) {\n  g.save(); rr(g, x, y, w, h, r); g.clip();\n  rr(g, x, y, w, h, 0, K.card);\n  circ(g, x + w * .72, y + h * .34, h * .14, K.yel);\n  poly(g, [[x, y + h], [x, y + h * .72], [x + w * .3, y + h * .38], [x + w * .55, y + h * .7], [x + w * .7, y + h * .52], [x + w, y + h * .8], [x + w, y + h]], K.red);\n  poly(g, [[x, y + h], [x, y + h * .86], [x + w * .45, y + h * .74], [x + w, y + h * .9], [x + w, y + h]], K.blue);\n  g.restore();\n}","b03Blob":"function b03Blob(g, cx, cy, w, h, r, fill) {\n  const [tl, tr, br, bl] = r, f = Math.min(1, 1 / Math.max(tl + tr, bl + br, tl + bl, tr + br));\n  const x = cx - w / 2, y = cy - h / 2, R4 = [tl, tr, br, bl].map(v => v * f);\n  g.beginPath();\n  g.ellipse(x + R4[0] * w, y + R4[0] * h, R4[0] * w, R4[0] * h, 0, Math.PI, Math.PI * 1.5);\n  g.ellipse(x + w - R4[1] * w, y + R4[1] * h, R4[1] * w, R4[1] * h, 0, Math.PI * 1.5, TAU);\n  g.ellipse(x + w - R4[2] * w, y + h - R4[2] * h, R4[2] * w, R4[2] * h, 0, 0, Math.PI / 2);\n  g.ellipse(x + R4[3] * w, y + h - R4[3] * h, R4[3] * w, R4[3] * h, 0, Math.PI / 2, Math.PI);\n  g.closePath(); g.fillStyle = fill; g.fill();\n}","b04ClipRR":"function b04ClipRR(g, x, y, w, h, r, fn) { g.save(); rr(g, x, y, w, h, r); g.clip(); fn(); g.restore(); }","b04View":"function b04View(g, x, y, w, h, fn, r = 12) { rr(g, x, y, w, h, r, K.paper, K.mute, 1.5); b04ClipRR(g, x + 1, y + 1, w - 2, h - 2, r - 1, fn); }","b04Thumb":"function b04Thumb(g, x, y, h, p, th = 30) { rr(g, x, y, 3, h, 1.5, K.grid); rr(g, x, y + clamp(p) * (h - th), 3, th, 1.5, K.mute); }","b04Finger":"function b04Finger(g, x, y, a = 1) { if (a <= 0) return; alpha(g, a, () => { alpha(g, .22, () => circ(g, x, y, 11, K.ink)); circ(g, x, y, 11, null, K.ink, 1.5); }); }","b04Dash":"function b04Dash(g, d, fn) { g.setLineDash(d); fn(); g.setLineDash([]); }","b04Num":"function b04Num(g, s, x, y, c, a, size) { tx(g, s, x, y, { size: size || 10, w: 500, f: 'm', c: c || K.ink, a: a || 'center' }); }","b04Check":"function b04Check(g, x, y, s, p, col, lw = 3) {\n  if (p <= 0) return;\n  const pts = [[-.42, .02], [-.12, .32], [.44, -.3]].map(([a, b]) => [x + a * s, y + b * s]);\n  const l1 = Math.hypot(pts[1][0] - pts[0][0], pts[1][1] - pts[0][1]), l2 = Math.hypot(pts[2][0] - pts[1][0], pts[2][1] - pts[1][1]), d = clamp(p) * (l1 + l2);\n  g.beginPath(); g.moveTo(pts[0][0], pts[0][1]);\n  if (d <= l1) g.lineTo(lerp(pts[0][0], pts[1][0], d / l1), lerp(pts[0][1], pts[1][1], d / l1));\n  else { g.lineTo(pts[1][0], pts[1][1]); const u = (d - l1) / l2; g.lineTo(lerp(pts[1][0], pts[2][0], u), lerp(pts[1][1], pts[2][1], u)); }\n  g.strokeStyle = col; g.lineWidth = lw; g.lineCap = 'round'; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; g.lineJoin = 'miter';\n}","b04Glow":"function b04Glow(g, x, y, r, col, a) { if (a <= 0) return; const n = 40, ai = 1 - Math.pow(1 - clamp(a), 1 / n); for (let i = 0; i < n; i++) alpha(g, ai, () => circ(g, x, y, r * Math.pow(1 - i / n, .8), col)); }","b04Shadow":"function b04Shadow(g, x, y, w, h, r, blur, a) { const n = 7, ai = 1 - Math.pow(1 - clamp(a), 1 / n); for (let i = 0; i < n; i++) { const e = blur * .5 * (i / (n - 1)); alpha(g, ai, () => rr(g, x - e, y - e, w + 2 * e, h + 2 * e, r + e, K.paper)); } }","b04Sim":"function b04Sim(t, target, k = 170, c = 26) {\n  const dt = 1 / 120, n = Math.floor(Math.max(0, t) / dt); let p = target(0).slice(); const v = p.map(() => 0);\n  for (let i = 0; i < n; i++) { const q = target(i * dt); for (let j = 0; j < p.length; j++) { v[j] += (k * (q[j] - p[j]) - c * v[j]) * dt; p[j] += v[j] * dt; } }\n  return p;\n}","b04Lag":"function b04Lag(t, target, tau) {\n  const dt = 1 / 120, n = Math.floor(Math.max(0, t) / dt), f = 1 - Math.exp(-dt / tau); let p = target(0).slice();\n  for (let i = 1; i <= n; i++) { const q = target(i * dt); for (let j = 0; j < p.length; j++) p[j] += (q[j] - p[j]) * f; }\n  return p;\n}","b04Inv":"function b04Inv(fn, target, a, b) { for (let i = 0; i < 30; i++) { const m = (a + b) / 2; if (fn(m) < target) a = m; else b = m; } return (a + b) / 2; }","b04Path":"function b04Path(d, s = 1, ox = 0, oy = 0) {\n  const tok = d.match(/[MLCSQ]|-?[\\d.]+/g); let i = 0, cmd = 'M', x = 0, y = 0, px = 0, py = 0; const pts = [], n = () => +tok[i++];\n  while (i < tok.length) {\n    if (/[MLCSQ]/.test(tok[i])) cmd = tok[i++];\n    if (cmd === 'M') { x = px = n(); y = py = n(); pts.push([x, y]); cmd = 'L'; }\n    else if (cmd === 'L') { x = px = n(); y = py = n(); pts.push([x, y]); }\n    else if (cmd === 'C' || cmd === 'S') {\n      let x1, y1; if (cmd === 'C') { x1 = n(); y1 = n(); } else { x1 = 2 * x - px; y1 = 2 * y - py; }\n      const x2 = n(), y2 = n(), x3 = n(), y3 = n();\n      for (let k = 1; k <= 28; k++) { const u = k / 28, a = (1 - u) ** 3, b = 3 * u * (1 - u) ** 2, c = 3 * u * u * (1 - u), e = u ** 3; pts.push([a * x + b * x1 + c * x2 + e * x3, a * y + b * y1 + c * y2 + e * y3]); }\n      px = x2; py = y2; x = x3; y = y3;\n    } else if (cmd === 'Q') {\n      const x1 = n(), y1 = n(), x2 = n(), y2 = n();\n      for (let k = 1; k <= 28; k++) { const u = k / 28, a = (1 - u) ** 2, b = 2 * u * (1 - u), e = u * u; pts.push([a * x + b * x1 + e * x2, a * y + b * y1 + e * y2]); }\n      px = x1; py = y1; x = x2; y = y2;\n    } else i++;\n  }\n  const P = pts.map(([a, b]) => [ox + a * s, oy + b * s]), Ls = [0];\n  for (let k = 1; k < P.length; k++) Ls.push(Ls[k - 1] + Math.hypot(P[k][0] - P[k - 1][0], P[k][1] - P[k - 1][1]));\n  return { P, L: Ls, len: Ls[Ls.length - 1] };\n}","b04At":"function b04At(p, f) { const d = clamp(f) * p.len; let k = 1; while (k < p.L.length - 1 && p.L[k] < d) k++; const l0 = p.L[k - 1], l1 = p.L[k], u = l1 > l0 ? (d - l0) / (l1 - l0) : 0; return [lerp(p.P[k - 1][0], p.P[k][0], u), lerp(p.P[k - 1][1], p.P[k][1], u), k]; }","b04Sub":"function b04Sub(g, p, a, b, col, lw, cap = 'round') {\n  a = clamp(a); b = clamp(b); if (b - a < 1e-4) return;\n  const s = b04At(p, a), e = b04At(p, b);\n  g.beginPath(); g.moveTo(s[0], s[1]); for (let k = s[2]; k < e[2]; k++) g.lineTo(p.P[k][0], p.P[k][1]); g.lineTo(e[0], e[1]);\n  g.strokeStyle = col; g.lineWidth = lw; g.lineCap = cap; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; g.lineJoin = 'miter';\n}","b04Meta":"function b04Meta(g, x1, y1, r1, x2, y2, r2, col) {\n  circ(g, x1, y1, r1, col); circ(g, x2, y2, r2, col);\n  const d = Math.hypot(x2 - x1, y2 - y1), v = .5, hs = 2.4, maxD = r1 + r2 * 2.5;\n  if (d > maxD || d <= Math.abs(r1 - r2)) return;\n  let u1 = 0, u2 = 0;\n  if (d < r1 + r2) { u1 = Math.acos(clamp((r1 * r1 + d * d - r2 * r2) / (2 * r1 * d), -1, 1)); u2 = Math.acos(clamp((r2 * r2 + d * d - r1 * r1) / (2 * r2 * d), -1, 1)); }\n  const ab = Math.atan2(y2 - y1, x2 - x1), ms = Math.acos(clamp((r1 - r2) / d, -1, 1));\n  const a1 = ab + u1 + (ms - u1) * v, a2 = ab - u1 - (ms - u1) * v, a3 = ab + Math.PI - u2 - (Math.PI - u2 - ms) * v, a4 = ab - Math.PI + u2 + (Math.PI - u2 - ms) * v;\n  const P = (cx, cy, a, r) => [cx + Math.cos(a) * r, cy + Math.sin(a) * r];\n  const p1 = P(x1, y1, a1, r1), p2 = P(x1, y1, a2, r1), p3 = P(x2, y2, a3, r2), p4 = P(x2, y2, a4, r2);\n  const tr = r1 + r2, d2 = Math.min(v * hs, Math.hypot(p1[0] - p3[0], p1[1] - p3[1]) / tr) * Math.min(1, d * 2 / tr);\n  const h1 = P(p1[0], p1[1], a1 - Math.PI / 2, r1 * d2), h2 = P(p2[0], p2[1], a2 + Math.PI / 2, r1 * d2), h3 = P(p3[0], p3[1], a3 + Math.PI / 2, r2 * d2), h4 = P(p4[0], p4[1], a4 - Math.PI / 2, r2 * d2);\n  g.beginPath(); g.moveTo(p1[0], p1[1]); g.bezierCurveTo(h1[0], h1[1], h3[0], h3[1], p3[0], p3[1]); g.lineTo(p4[0], p4[1]); g.bezierCurveTo(h4[0], h4[1], h2[0], h2[1], p2[0], p2[1]); g.closePath(); g.fillStyle = col; g.fill();\n}","b04Scene":"function b04Scene(g, x, y, w, h) {\n  rr(g, x, y, w, h, 0, K.card);\n  circ(g, x + w * .72, y + h * .32, h * .12, K.red);\n  poly(g, [[x, y + h], [x, y + h * .62], [x + w * .22, y + h * .38], [x + w * .44, y + h * .6], [x + w * .62, y + h * .44], [x + w, y + h * .7], [x + w, y + h]], K.line);\n  poly(g, [[x, y + h], [x, y + h * .82], [x + w * .3, y + h * .6], [x + w * .55, y + h * .84], [x + w * .8, y + h * .66], [x + w, y + h * .8], [x + w, y + h]], K.blue);\n}","b04GF":"const b04GF = b04Path('M12 87 C42 8 70 111 107 57 S168 13 208 62', 1.4, 6, 16);","b04Sig":"const b04Sig = [b04Path('M18 84 C39 4 67 6 52 70 C35 120 40 66 68 59', 1.4, 6, 8), b04Path('M63 62 C74 31 78 84 95 66 S115 46 125 64 S146 45 162 63', 1.4, 6, 8), b04Path('M39 95 Q108 79 199 83', 1.4, 6, 8)];","b05Win":"function b05Win(g, x, y, w, h, fn) {\n  rr(g, x, y, w, h, 8, K.card, K.grid, 1);\n  g.save(); rr(g, x, y, w, h, 8); g.clip(); g.beginPath(); g.rect(x, y + 14, w, h - 14); g.clip();\n  fn(x, y + 14, w, h - 14);\n  g.restore();\n  for (let i = 0; i < 3; i++) circ(g, x + 9 + i * 7, y + 7, 2, K.line);\n  ln(g, x, y + 14, x + w, y + 14, K.grid, 1);\n  rr(g, x, y, w, h, 8, null, K.grid, 1);\n}","b05PageA":"function b05PageA(g, x, y, w, h) {\n  rr(g, x, y, w, h, 0, K.card);\n  rr(g, x + 10, y + 9, Math.min(60, w * .35), 6, 3, K.ink);\n  const n = Math.floor((h - 24) / 22);\n  for (let i = 0; i < n; i++) { const ry = y + 22 + i * 22; rr(g, x + 10, ry, w - 20, 17, 4, K.grid); circ(g, x + 19, ry + 8.5, 4, i === 1 ? K.blue : K.mute); rr(g, x + 28, ry + 6.5, (w - 50) * (i % 2 ? .45 : .65), 4, 2, K.mute); }\n}","b05PageB":"function b05PageB(g, x, y, w, h, back = true, hero) {\n  rr(g, x, y, w, h, 0, K.line);\n  if (back) { ln(g, x + 14, y + 8, x + 10, y + 12, K.ink, 1.5); ln(g, x + 10, y + 12, x + 14, y + 16, K.ink, 1.5); }\n  rr(g, x + (back ? 22 : 10), y + 9, Math.min(44, w * .3), 6, 3, K.ink);\n  rr(g, x + 10, y + 22, w - 20, h * .36, 6, hero || K.red);\n  const by = y + 32 + h * .36;\n  for (let i = 0; i < 3; i++) if (by + i * 12 + 4 < y + h - 4) rr(g, x + 10, by + i * 12, (w - 20) * [.8, .55, .7][i], 4, 2, K.mute);\n}","b05Quint":"const b05Quint = x => x < .5 ? 16 * x ** 5 : 1 - (-2 * x + 2) ** 5 / 2;","b05Cur":"function b05Cur(g, t, xs, ys, presses = [], a = 1) {\n  const press = presses.some(([p0, p1]) => t > p0 && t < p1) ? 1 : 0;\n  alpha(g, a, () => cursor(g, kf(t, xs, E.inOut), kf(t, ys, E.inOut), press));\n}","b05Num":"function b05Num(g, s, x, y, c, a = 'center') { tx(g, s, x, y, { size: 9, f: 'm', w: 500, c: c || K.mute, a }); }","b05Img":"function b05Img(g, x, y, w, h, r, main) {\n  g.save(); rr(g, x, y, w, h, r); g.clip();\n  rr(g, x, y, w, h, 0, main ? K.red : K.grid);\n  const s = Math.max(w / 72, h / 50), cx = x + w / 2, by = y + h, P = pts => pts.map(([px, py]) => [cx + px * s, by + py * s]);\n  alpha(g, main ? .55 : 1, () => circ(g, cx - 18 * s, by - 36 * s, 5 * s, main ? K.paper : K.line));\n  alpha(g, main ? .35 : 1, () => poly(g, P([[-90, 0], [-90, -10], [-30, -30], [-4, -16], [22, -34], [90, -8], [90, 0]]), main ? K.paper : K.line));\n  alpha(g, main ? .6 : 1, () => poly(g, P([[-90, 0], [-90, -6], [-24, -15], [36, -4], [90, -12], [90, 0]]), main ? K.paper : K.mute));\n  g.restore();\n}","b06Path":"function b06Path(g, x, y, w, h, r) { r = Math.max(0, Math.min(r, w / 2, h / 2)); g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath(); }","b06Clip":"function b06Clip(g, x, y, w, h, r, fn) { g.save(); b06Path(g, x, y, w, h, r); g.clip(); fn(); g.restore(); }","b06Line":"function b06Line(g, pts, p, c, lw) {\n  let L = 0; const seg2 = []; for (let i = 1; i < pts.length; i++) { const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); seg2.push(d); L += d; }\n  let left = L * clamp(p); if (left <= 0) return; g.beginPath(); g.moveTo(pts[0][0], pts[0][1]);\n  for (let i = 1; i < pts.length && left > 0; i++) { const k = Math.min(1, left / seg2[i - 1]); g.lineTo(lerp(pts[i - 1][0], pts[i][0], k), lerp(pts[i - 1][1], pts[i][1], k)); left -= seg2[i - 1]; }\n  g.strokeStyle = c; g.lineWidth = lw; g.lineCap = 'round'; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; g.lineJoin = 'miter';\n}","b06Check":"function b06Check(g, x, y, s, p, c, lw = 3) { b06Line(g, [[x - s, y], [x - s * .32, y + s * .62], [x + s, y - s * .68]], p, c, lw); }","b06RRLen":"function b06RRLen(w, h, r) { return 2 * (w - 2 * r) + 2 * (h - 2 * r) + TAU * r; }","b06RRPt":"function b06RRPt(x, y, w, h, r, s) {\n  const a = w - 2 * r, b = h - 2 * r, q = Math.PI * r / 2, L = b06RRLen(w, h, r); s = ((s % L) + L) % L;\n  const S = [['l', x + r, y, 1, 0, a], ['c', x + w - r, y + r, -Math.PI / 2], ['l', x + w, y + r, 0, 1, b], ['c', x + w - r, y + h - r, 0], ['l', x + w - r, y + h, -1, 0, a], ['c', x + r, y + h - r, Math.PI / 2], ['l', x, y + h - r, 0, -1, b], ['c', x + r, y + r, Math.PI]];\n  for (const e of S) { const len = e[0] === 'l' ? e[5] : q; if (s <= len) return e[0] === 'l' ? [e[1] + e[3] * s, e[2] + e[4] * s] : [e[1] + Math.cos(e[3] + s / r) * r, e[2] + Math.sin(e[3] + s / r) * r]; s -= len; }\n  return [x + r, y];\n}","b06Graph":"function b06Graph(g, fn, t, dur, o) {\n  const x0 = o.x0 || 40, x1 = o.x1 || 280, X = s => lerp(x0, x1, s / dur), Y = v => lerp(o.y1, o.y0, (v - o.lo) / (o.hi - o.lo)), c = o.c || K.red;\n  if (o.base != null) ln(g, x0, Y(o.base), x1, Y(o.base), K.grid, 1, [3, 3]);\n  const path = upto => { g.beginPath(); const n = Math.ceil(140 * upto / dur); for (let i = 0; i <= n; i++) { const s = Math.min(upto, i / 140 * dur); g.lineTo(X(s), Y(fn(s))); } };\n  path(dur); g.strokeStyle = K.grid; g.lineWidth = 1.5; g.stroke();\n  path(t); g.strokeStyle = c; g.lineWidth = 2; g.stroke();\n  circ(g, X(t), Y(fn(t)), 3.2, c);\n}","b06Read":"function b06Read(g, s, x = 308, y = 14, c) { tx(g, s, x, y, { a: 'right', size: 10, w: 500, f: 'm', c: c || K.ink }); }","b06Cur":"function b06Cur(g, t, keys, press) {\n  let x = keys[0][1], y = keys[0][2];\n  for (let i = 1; i < keys.length; i++) { const [t0, x0, y0] = keys[i - 1], [t1, x1, y1] = keys[i]; if (t >= t0) { const q = E.inOut(clamp((t - t0) / (t1 - t0))), arc = Math.sin(q * Math.PI) * .1; x = lerp(x0, x1, q) - (y1 - y0) * arc; y = lerp(y0, y1, q) + (x1 - x0) * arc; } }\n  cursor(g, x, y, press);\n}","b06BounceS":"const b06BounceS = t => { const tp = .7, tr = 1.25; if (t < tp) return 1; if (t < tr) return lerp(1, .92, seg(t, tp, tp + .1, E.outCubic)); if (t < tr + .16) return lerp(.92, 1.05, E.outQuad(clamp((t - tr) / .16))); return lerp(1.05, 1, E.inOut(clamp((t - tr - .16) / .3))); };","b06Jelly":"const b06Jelly = t => { const d = t - .55; if (d <= 0) return 0; return .2 * Math.exp(-3.4 * d) * Math.cos(d * 17) * E.outQuad(clamp(d / .05)) * (1 - seg(d, 1.6, 2)); };","b06Shake":"const b06Shake = t => { const d = t - .65; if (d <= 0) return 0; return 9 * Math.exp(-6 * d) * Math.sin(d * 44) * (1 - seg(d, .45, .6)); };","b06Depth":"const b06Depth = t => t < .7 ? 8 : t < 1.3 ? lerp(8, 2, seg(t, .7, .8, E.outCubic)) : lerp(2, 8, spring(t - 1.3, 420, 24));","b06Hold":"const b06Hold = t => { if (t < .4) return 0; if (t < 1.0) return (t - .4) / 1.2; if (t < 1.6) return .5 * (1 - E.outCubic(clamp((t - 1.0) / .25))); return Math.min(1, (t - 1.6) / 1.2); };","b06Beat":"const b06Beat = (c, t0, amp) => c < t0 ? 0 : c < t0 + .08 ? amp * E.outQuad((c - t0) / .08) : amp * (1 - E.inOut(clamp((c - t0 - .08) / .22)));","b06Heart":"const b06Heart = t => { const c = t % 1.4; return 1 + b06Beat(c, .15, .2) + b06Beat(c, .45, .1); };","b06Tilt":"const b06Tilt = t => { const d = t - .5; if (d <= 0) return 0; return .24 * Math.exp(-2.4 * d) * Math.sin(d * 9) * (1 - seg(d, 1.5, 1.9)); };","b06Inset":"const b06Inset = t => seg(t, .7, .82, E.outCubic) * (1 - seg(t, 1.6, 1.85, E.outCubic));","b06Breath":"const b06Breath = t => .5 - .5 * Math.cos(t / 2.8 * TAU);","b07TabX":"const b07TabX = [88, 160, 232], b07Tabs = ['HOME', 'WORK', 'SAVE'];","b07Moves":"const b07Moves = [[.3, 0, 1], [1.15, 1, 2], [2.0, 2, 0]];","b07Sel":"function b07Sel(t, moves) { let s = moves[0][1]; moves.forEach(([t0, a, b]) => { if (t >= t0) s = b; }); return s; }","b07Edges":"function b07Edges(t, moves, w, fastD = .26, lag = .09, slowD = .34) {\n  let L = b07TabX[moves[0][1]] - w / 2, R = L + w;\n  moves.forEach(([t0, a, b]) => { const d = b07TabX[b] - b07TabX[a], f = seg(t, t0, t0 + fastD, E.outCubic), s = seg(t, t0 + lag, t0 + lag + slowD, E.inOutCubic); if (d > 0) { R += d * f; L += d * s; } else { L += d * f; R += d * s; } });\n  return [L, R];\n}","b07Goo":"function b07Goo(g, xa, ra, xb, rb, c, reach = 70, start = .4) {\n  if (xa > xb) { [xa, xb] = [xb, xa]; [ra, rb] = [rb, ra]; }\n  circ(g, xa, 0, ra, c); circ(g, xb, 0, rb, c);\n  const d = xb - xa, n = Math.min(ra, rb) * .82 * (1 - clamp((d - (ra + rb) * start) / reach));\n  if (n > .4 && d > 1) { const m = (xa + xb) / 2; g.beginPath(); g.moveTo(xa, -ra * .82); g.quadraticCurveTo(m, -n, xb, -rb * .82); g.lineTo(xb, rb * .82); g.quadraticCurveTo(m, n, xa, ra * .82); g.closePath(); g.fillStyle = c; g.fill(); }\n}","b07Path":"function b07Path(g, pts, p, c, w) {\n  if (p <= 0) return; let L = 0; const ls = []; for (let i = 1; i < pts.length; i++) { const l = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); ls.push(l); L += l; }\n  let rem = L * clamp(p); g.beginPath(); g.moveTo(...pts[0]);\n  for (let i = 1; i < pts.length && rem > 0; i++) { const k = Math.min(1, rem / ls[i - 1]); g.lineTo(lerp(pts[i - 1][0], pts[i][0], k), lerp(pts[i - 1][1], pts[i][1], k)); rem -= ls[i - 1]; }\n  g.strokeStyle = c; g.lineWidth = w; g.lineCap = 'round'; g.lineJoin = 'round'; g.stroke(); g.lineCap = 'butt'; g.lineJoin = 'miter';\n}","b07Heart":"function b07Heart(g, x, y, r, fill, stroke, lw) { poly(g, shapePts('heart', x, y, r, 48), fill, stroke, lw); }","b07TabLabels":"function b07TabLabels(g, k) { b07Tabs.forEach((s, i) => { tx(g, s, b07TabX[i], 96, { size: 12, f: 'm', w: 700, c: K.mute }); alpha(g, k(i), () => tx(g, s, b07TabX[i], 96, { size: 12, f: 'm', w: 700, c: K.ink })); }); }","b08Loop":"function b08Loop(t, dur, out = .36) { const m = dur - out / 2; return t < m ? [t, 1 - seg(t, dur - out, m, E.inQuad)] : [0, seg(t, m, dur, E.outQuad)]; }","b08Coin":"function b08Coin(g, x, y, r, sx = 1, c = K.red) { if (r <= .2) return; xf(g, x, y, Math.max(.12, Math.abs(sx)), 1, 0, () => { circ(g, 0, 0, r, c); circ(g, 0, 0, r * .58, null, K.paper, Math.max(1, r * .16)); }); }","b08Burst":"function b08Burst(g, x, y, p, n, R, seed, cols, sz = 2.6) { if (p <= 0 || p >= 1) return; const r = rng(seed); for (let i = 0; i < n; i++) { const a = i / n * TAU + (r() - .5) * .6, d = R * (.55 + r() * .45) * E.outCubic(p); alpha(g, 1 - E.inQuad(p), () => circ(g, x + Math.cos(a) * d, y + Math.sin(a) * d, sz * (1 - p * .5), cols[i % cols.length])); } }","b08Pop":"function b08Pop(t, t0, d = .3) { return seg(t, t0, t0 + d, E.outBack); }","b08Bolt":"function b08Bolt(g, x, y, s, c) { xf(g, x, y, s, s, 0, () => poly(g, [[3, -10], [-6, 2], [-1, 2], [-3, 10], [6, -2], [1, -2]], c)); }","b08Shake":"function b08Shake(t, a, b, amp, seed = 0) { if (t < a || t > b) return 0; return (hash(Math.floor(t * 60) + seed) - .5) * 2 * amp * (1 - (t - a) / (b - a)); }","b08Q":"function b08Q(p0, c, p1, u) { const a = 1 - u; return [a * a * p0[0] + 2 * a * u * c[0] + u * u * p1[0], a * a * p0[1] + 2 * a * u * c[1] + u * u * p1[1]]; }","b08Arc":"function b08Arc(g, x, y, r, a0, a1, c, w) { if (a1 - a0 < .01) return; g.beginPath(); g.arc(x, y, r, a0, a1); g.strokeStyle = c; g.lineWidth = w; g.lineCap = 'round'; g.stroke(); g.lineCap = 'butt'; }","b08Rays":"function b08Rays(g, cx, cy, angs, len, hw, c, a) { [1, .68, .4].forEach(k => alpha(g, a * .22, () => angs.forEach(an => poly(g, [[cx, cy], [cx + Math.cos(an - hw) * len * k, cy + Math.sin(an - hw) * len * k], [cx + Math.cos(an + hw) * len * k, cy + Math.sin(an + hw) * len * k]], c)))); }","b08Ell":"function b08Ell(g, x, y, rx, ry, fill, stroke, lw = 1.5) { g.beginPath(); g.ellipse(x, y, Math.max(0, rx), Math.max(0, ry), 0, 0, TAU); if (fill) { g.fillStyle = fill; g.fill(); } if (stroke) { g.strokeStyle = stroke; g.lineWidth = lw; g.stroke(); } }","b08Sword":"function b08Sword(g, x, y, s, c) { xf(g, x, y, s, s, -Math.PI / 4, () => { poly(g, [[-3, 8], [-3, -16], [0, -21], [3, -16], [3, 8]], c); rr(g, -9, 7, 18, 4, 2, c); rr(g, -2, 11, 4, 8, 1.5, c); }); }","b08Gem":"function b08Gem(g, x, y, s, c) { xf(g, x, y, s, s, 0, () => { poly(g, [[-10, -4], [-5, -10], [5, -10], [10, -4], [0, 10]], c); alpha(g, .35, () => poly(g, [[-5, -10], [5, -10], [2, -4], [-2, -4]], K.paper)); }); }","b08Shield":"function b08Shield(g, fill, stroke) { poly(g, [[-34, -40], [34, -40], [34, -6], [28, 14], [16, 32], [0, 46], [-16, 32], [-28, 14], [-34, -6]], fill, stroke, 2); }","b08TW":"function b08TW(g, s, size) { g.font = `800 ${size}px ${FONT.d}`; return g.measureText(L(s)).width; }","b09Shake":"function b09Shake(t, t0, d = .16, a = 4, s = 1) { const k = (t - t0) / d; if (k <= 0 || k >= 1) return [0, 0]; const f = Math.floor(t * 60); return [(hash(f * 3 + s) - .5) * 2 * a * (1 - k), (hash(f * 7 + s + 1) - .5) * 2 * a * (1 - k)]; }","b09Check":"function b09Check(g, x, y, s, p, col, lw = 3) { if (p <= 0) return; g.save(); g.translate(x, y); g.scale(s, s); g.beginPath(); g.moveTo(-8, 0); g.lineTo(-2.5, 6); g.lineTo(9, -6.5); g.strokeStyle = col; g.lineWidth = lw / s; g.lineCap = 'round'; g.lineJoin = 'round'; g.setLineDash([30, 30]); g.lineDashOffset = 30 * (1 - clamp(p)); g.stroke(); g.restore(); }","b09Lock":"function b09Lock(g, x, y, s, col) { xf(g, x, y, s, s, 0, () => { g.beginPath(); g.arc(0, -3, 4.5, Math.PI, 0); g.lineTo(4.5, 0); g.moveTo(-4.5, 0); g.lineTo(-4.5, -3); g.strokeStyle = col; g.lineWidth = 2; g.stroke(); rr(g, -7, -1, 14, 11, 2, col); circ(g, 0, 4, 1.6, K.paper); }); }","b09Gem":"function b09Gem(g, x, y, r, fill) { poly(g, [[x, y - r], [x + r * .85, y - r * .25], [x, y + r], [x - r * .85, y - r * .25]], fill); alpha(g, .45, () => { ln(g, x - r * .85, y - r * .25, x + r * .85, y - r * .25, K.paper, 1); ln(g, x, y - r, x, y + r, K.paper, 1); }); }","b09Shield":"function b09Shield(g, x, y, s, fill, stroke, lw = 2) { xf(g, x, y, s, s, 0, () => poly(g, [[0, -34], [28, -24], [26, 8], [0, 34], [-26, 8], [-28, -24]], fill, stroke, lw / s)); }","b09Stripes":"function b09Stripes(g, x, y, w, h, off, col) { clip(g, x, y, w, h, () => { rr(g, x, y, w, h, 0, col); for (let i = -2; i < w / 18 + 3; i++) { const sx = x + i * 18 + (off % 18); poly(g, [[sx, y], [sx + 9, y], [sx + 9 - h, y + h], [sx - h, y + h]], K.paper); } }); }","b09Roll":"function b09Roll(g, a, b, p, x, y, h, o) { tx(g, a, x, y - p * h, o); tx(g, b, x, y + h - p * h, o); }","b09Blade":"function b09Blade(g, px, py, ang, col) { xf(g, px, py, 1, 1, ang, () => { rr(g, -2.5, 0, 5, 18, 2, K.line); rr(g, -11, -4, 22, 6, 2, K.mute); poly(g, [[-3.5, -4], [3.5, -4], [3, -104], [0, -116], [-3, -104]], col); alpha(g, .35, () => ln(g, 0, -8, 0, -104, K.paper, 1)); }); }","b09Edge":"function b09Edge(g, a, d) { if (a <= 0) return; const c0 = K.red, c1 = K.red + '00'; alpha(g, a, () => { [[0, 0, 0, d, 0, 0, W, d], [0, H, 0, H - d, 0, H - d, W, d], [0, 0, d, 0, 0, 0, d, H], [W, 0, W - d, 0, W - d, 0, d, H]].forEach(([x0, y0, x1, y1, rx, ry, rw, rh]) => { const gr = g.createLinearGradient(x0, y0, x1, y1); gr.addColorStop(0, c0); gr.addColorStop(1, c1); g.fillStyle = gr; g.fillRect(rx, ry, rw, rh); }); }); }","b10P":"const b10P = (x, y, z, cx = 160, cy = 100, f = 360) => { const s = f / (f + z); return [cx + x * s, cy + y * s, s]; };","b10Map":"function b10Map(x, y, z, rx = 0, ry = 0, cx = 160, cy = 100, f = 360) {\n  const cX = Math.cos(rx), sX = Math.sin(rx), cY = Math.cos(ry), sY = Math.sin(ry);\n  return (u, v) => { const X = u, Y = v * cX, Z = v * sX; return b10P(x + X * cY + Z * sY, y + Y, z - X * sY + Z * cY, cx, cy, f); };\n}","b10Quad":"function b10Quad(g, M, x0, y0, w, h, fill, stroke, lw = 1.5) { poly(g, [M(x0, y0), M(x0 + w, y0), M(x0 + w, y0 + h), M(x0, y0 + h)].map(p => [p[0], p[1]]), fill, stroke, lw); }","b10Face":"function b10Face(M, w, h) { const a = M(0, 0), b = M(w, 0), c = M(0, h); return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]); }","b10On":"function b10On(g, M, u0, v0, fn) { const o = M(u0, v0), a = M(u0 + 1, v0), b = M(u0, v0 + 1); g.save(); g.transform(a[0] - o[0], a[1] - o[1], b[0] - o[0], b[1] - o[1], o[0], o[1]); fn(); g.restore(); }","b10Dash":"function b10Dash(g, fn, d = [3, 3]) { g.setLineDash(d); fn(); g.setLineDash([]); }","b10Read":"function b10Read(g, s, x, y, a = 'right', c) { tx(g, s, x, y, { a, size: 9, w: 500, f: 'm', c: c || K.mute }); }","b10Icon":"function b10Icon(g, k, x, y, c) {\n  g.save(); g.translate(x, y); g.strokeStyle = c; g.fillStyle = c; g.lineWidth = 1.8; g.lineCap = 'round';\n  if (k === 0) star(g, 0, 0, 7, 3, 4, c);\n  else if (k === 1) { g.beginPath(); g.arc(-1.5, -1.5, 4.5, 0, TAU); g.stroke(); ln(g, 2, 2, 6, 6, c, 1.8); }\n  else if (k === 2) rr(g, -5, -5, 10, 10, 2, null, c, 1.8);\n  else if (k === 3) { ln(g, -5, 5, 5, -5, c, 1.8); ln(g, 0, -5, 5, -5, c, 1.8); ln(g, 5, -5, 5, 0, c, 1.8); }\n  else if (k === 4) poly(g, shapePts('heart', 0, 1, 7, 40), c);\n  else if (k === 5) poly(g, [[0, -6], [6, 0], [0, 6], [-6, 0]], c);\n  else if (k === 6) { ln(g, -5, -4, 5, -4, c, 1.8); rr(g, -4, -2, 8, 8, 1.5, null, c, 1.8); }\n  g.lineCap = 'butt'; g.restore();\n}","b10LensWorld":"function b10LensWorld(g, lw) {\n  g.lineWidth = lw; g.strokeStyle = K.grid; g.beginPath();\n  for (let x = 24; x <= 296; x += 16) { g.moveTo(x, 28); g.lineTo(x, 180); }\n  for (let y = 28; y <= 180; y += 16) { g.moveTo(24, y); g.lineTo(296, y); }\n  g.stroke();\n  const r = rng(1010);\n  for (let i = 0; i < 26; i++) { const x = 24 + Math.floor(r() * 17) * 16 + 8, y = 28 + Math.floor(r() * 9) * 16 + 8, k = r(); if (k < .3) circ(g, x, y, 3, K.blue); else if (k < .7) rr(g, x - 3, y - 3, 6, 6, 1, K.mute); else circ(g, x, y, 2, K.ink); }\n}","b10World":"function b10World(g, s) {\n  g.fillStyle = K.grid; for (let x = -360; x <= 400; x += 40) for (let y = -160; y <= 160; y += 40) { g.beginPath(); g.arc(x, y, 1.6 / s, 0, TAU); g.fill(); }\n  [[-40, -110, 70, 44], [60, 40, 90, 56], [-200, 70, 80, 50], [180, -120, 76, 46], [-330, -140, 60, 38], [320, 120, 50, 34]].forEach(([x, y, w, h]) => { rr(g, x, y, w, h, 6, K.card, K.line, 1 / s); rr(g, x + 8, y + 8, w * .5, 6, 3, K.mute); });\n  rr(g, -300, -80, 100, 66, 8, K.card, K.ink, 1.5 / s); tx(g, 'A', -250, -47, { size: 26, f: 'd', c: K.ink });\n  rr(g, 220, 30, 100, 66, 8, K.red); tx(g, 'B', 270, 63, { size: 26, f: 'd', c: K.paper });\n}","b11Neck":"function b11Neck(g, x1, y, r1, x2, r2, wm, fill) {\n  if (wm <= .25 || x2 - x1 < 1) return;\n  const f = clamp(wm / Math.min(r1, r2)), ph = lerp(.55, 1.45, f), c1 = Math.cos(ph), s1 = Math.sin(ph);\n  const ax = x1 + r1 * c1, ay = r1 * s1, bx = x2 - r2 * c1, by = r2 * s1, mx = (ax + bx) / 2, cy = 2 * wm - (ay + by) / 2;\n  g.beginPath(); g.moveTo(ax, y - ay); g.quadraticCurveTo(mx, y - cy, bx, y - by); g.lineTo(bx, y + by); g.quadraticCurveTo(mx, y + cy, ax, y + ay); g.closePath();\n  g.fillStyle = fill; g.fill();\n}","b11Vel":"const b11Vel = (fn, t, h = .004) => (fn(t + h) - fn(t - h)) / (2 * h);","b11Path":"function b11Path(g, subs, len) {\n  g.beginPath(); let rem = len, head = null;\n  for (const pts of subs) {\n    if (rem <= 0) break; g.moveTo(pts[0][0], pts[0][1]); head = pts[0];\n    for (let k = 1; k < pts.length && rem > 0; k++) { const [ax, ay] = pts[k - 1], [bx, by] = pts[k], d = Math.hypot(bx - ax, by - ay), u = Math.min(1, rem / d); head = [lerp(ax, bx, u), lerp(ay, by, u)]; g.lineTo(head[0], head[1]); rem -= d; }\n  }\n  return head;\n}","b11Len":"const b11Len = subs => subs.reduce((s, pts) => s + pts.reduce((a, p, i) => i ? a + Math.hypot(p[0] - pts[i - 1][0], p[1] - pts[i - 1][1]) : 0, 0), 0);","b11Pill":"function b11Pill(g, cx, y, sx, sy, fill) { const w = 60 * sx, h = 44 * sy; rr(g, cx - w / 2, y - h / 2, w, h, h / 2, fill); return { r: h / 2, off: w / 2 - h / 2 }; }","b11GlassArt":"function b11GlassArt(g) {\n  for (let x = 16; x <= 304; x += 16) ln(g, x, 26, x, 182, K.line, 1);\n  for (let y = 26; y <= 182; y += 16) ln(g, 16, y, 304, y, K.line, 1);\n  for (let x = 16; x <= 304; x += 64) ln(g, x, 26, x, 182, K.mute, 1);\n  for (let y = 42; y <= 182; y += 64) ln(g, 16, y, 304, y, K.mute, 1);\n  [[64, 132, K.grid, 8], [128, 100, K.blue, 8], [224, 108, K.blue, 6], [272, 70, K.grid, 8]].forEach(([x, y, c, r]) => circ(g, x, y, r, c));\n}","b11Lock":"function b11Lock(g, x, y, open, c) { rr(g, x - 13, y - 4, 26, 21, 4, c); g.beginPath(); g.arc(x, y - 4 - open * 7, 8, Math.PI, Math.PI * 2 - (open ? .0 : 0)); g.lineTo(x + 8, y - 4 + (open ? -7 : 0)); g.strokeStyle = c; g.lineWidth = 3; g.stroke(); }","b11Cracks":"function b11Cracks() {\n  const rn = rng(7), rays = [], br = [];\n  for (let i = 0; i < 7; i++) {\n    const a = i / 7 * TAU + (rn() - .5) * .5, lim = Math.min(84 / Math.max(.01, Math.abs(Math.cos(a))), 54 / Math.max(.01, Math.abs(Math.sin(a)))) * (.72 + rn() * .2);\n    const pts = [[160, 100]]; let x = 160, y = 100, aa = a;\n    for (let k = 0; k < 4; k++) { aa = a + (rn() - .5) * .55; x += Math.cos(aa) * lim / 4; y += Math.sin(aa) * lim / 4; pts.push([x, y]); }\n    rays.push(pts);\n    if (i % 2 === 0) { const [bx, by] = pts[2], ba = a + (rn() > .5 ? .7 : -.7), bl = 14 + rn() * 10; br.push({ i, pts: [[bx, by], [bx + Math.cos(ba) * bl * .5, by + Math.sin(ba) * bl * .5 + 2], [bx + Math.cos(ba) * bl, by + Math.sin(ba) * bl]] }); }\n  }\n  return { rays, br };\n}","b11Neon":"function b11Neon() {\n  const s = 1.15, ox = 10.5, oy = 12, P = (x, y) => [ox + x * s, oy + y * s];\n  const O = []; for (let i = 0; i <= 40; i++) { const a = -Math.PI / 2 - i / 40 * TAU; O.push(P(155 + Math.cos(a) * 17, 75 + Math.sin(a) * 25)); }\n  return [[P(38, 100), P(38, 50), P(70, 100), P(70, 50)], [P(118, 50), P(90, 50), P(90, 100), P(120, 100)], [P(90, 75), P(114, 75)], O, [P(190, 100), P(190, 50), P(222, 100), P(222, 50)]];\n}","b12Base":"const b12Base = (cy, size) => cy + size * .36;","b12Arrow":"function b12Arrow(g, x1, y1, x2, y2, c, w = 1.5) { ln(g, x1, y1, x2, y2, c, w); const a = Math.atan2(y2 - y1, x2 - x1); poly(g, [[x2, y2], [x2 - Math.cos(a - .5) * 6, y2 - Math.sin(a - .5) * 6], [x2 - Math.cos(a + .5) * 6, y2 - Math.sin(a + .5) * 6]], c); }","b12Stroke":"function b12Stroke() {\n  const segs = [], P = (x, y) => [44 + (x - 35) * 1.27, 108 + (y - 80) * 1.27];\n  let cur = [35, 93], prevC = null;\n  const add = (c1, c2, e) => { segs.push([cur, c1, c2, e]); prevC = c2; cur = e; };\n  add([55, 25], [49, 113], [67, 86]);\n  [[[82, 64], [87, 86]], [[103, 50], [110, 72]], [[117, 105], [133, 85]], [[149, 61], [154, 80]], [[176, 92], [182, 69]], [[184, 103], [218, 70]]].forEach(([c2, e]) => add([2 * cur[0] - prevC[0], 2 * cur[1] - prevC[1]], c2, e));\n  const pts = [];\n  segs.forEach(([a, b, c, d], si) => { for (let i = si ? 1 : 0; i <= 40; i++) { const u = i / 40, v = 1 - u; pts.push(P(v * v * v * a[0] + 3 * v * v * u * b[0] + 3 * v * u * u * c[0] + u * u * u * d[0], v * v * v * a[1] + 3 * v * v * u * b[1] + 3 * v * u * u * c[1] + u * u * u * d[1])); } });\n  const len = [0]; for (let i = 1; i < pts.length; i++) len.push(len[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));\n  return { pts, len, total: len[len.length - 1] };\n}","b12Path":"const b12Path = b12Stroke();","b12At":"function b12At(d) { const { pts, len } = b12Path; let i = 1; while (i < len.length - 1 && len[i] < d) i++; const u = clamp((d - len[i - 1]) / (len[i] - len[i - 1] || 1)); return [lerp(pts[i - 1][0], pts[i][0], u), lerp(pts[i - 1][1], pts[i][1], u)]; }","b12Fall":"function b12Fall(dt, D) {\n  // 자유낙하 → 튀는 높이 26 → 8 → 2px. 반환값 [바닥으로부터의 높이, 착지 충격 0..1]\n  const T0 = .46, a = 2 * D / (T0 * T0), hs = [26, 8, 2];\n  if (dt <= 0) return [D, 0];\n  if (dt < T0) return [D - a * dt * dt / 2, 0];\n  let s = dt - T0, imp = 1;\n  for (const h of hs) { const T = 2 * Math.sqrt(2 * h / a); if (s < T) { const v0 = Math.sqrt(2 * a * h), y = v0 * s - a * s * s / 2; return [y, Math.max(0, 1 - s / .07) * imp]; } s -= T; imp *= Math.sqrt(h / (h === 26 ? D : 26)) * 1.1; }\n  return [0, Math.max(0, 1 - s / .07) * imp];\n}","b12Flow":"function b12Flow(g, w) {\n  g.font = `800 26px ${FONT.d}`; const ws = ['MAKE', 'IT', 'MOVE'].map(s => [s, g.measureText(s).width]), pad = 14, gap = 10; let x = pad, y = 0; const out = [];\n  ws.forEach(([s, ww]) => { if (x > pad && x + ww > w - pad) { x = pad; y++; } out.push([s, x, y, ww]); x += ww + gap; });\n  return out;\n}","b12Hinge":"function b12Hinge(g, c, hx, hy, size, th, col) {\n  // 상단 경첩(rotateX). 가로 밴드로 나눠 원근로 폭을 바꿈\n  const S = 12, capH = size * .74, F = 260, sh = capH / S, cth = Math.cos(th), sth = Math.sin(th);\n  for (let j = 0; j < S; j++) {\n    const d0 = j * sh, d1 = (j + 1) * sh, dm = (d0 + d1) / 2, k = F / (F + dm * sth), y0 = d0 * cth * F / (F + d0 * sth), y1 = d1 * cth * F / (F + d1 * sth);\n    if (Math.abs(y1 - y0) < .05) continue;\n    g.save(); g.beginPath(); g.rect(hx - size, hy + Math.min(y0, y1) - .3, size * 2, Math.abs(y1 - y0) + .6); g.clip();\n    g.translate(hx, hy + y0); g.scale(k, (y1 - y0) / sh); g.translate(0, -d0);\n    drawChar(g, c, 0, capH, size, col); g.restore();\n  }\n}","b13Path":"function b13Path(g, pts, p, c, w = 2.5, dash) {\n  let tot = 0; for (let i = 1; i < pts.length; i++) tot += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);\n  let rem = clamp(p) * tot, hx = pts[0][0], hy = pts[0][1];\n  g.beginPath(); g.moveTo(hx, hy);\n  for (let i = 1; i < pts.length; i++) {\n    const [x0, y0] = pts[i - 1], [x1, y1] = pts[i], d = Math.hypot(x1 - x0, y1 - y0);\n    if (rem >= d) { g.lineTo(x1, y1); rem -= d; hx = x1; hy = y1; } else { const k = rem / d; hx = lerp(x0, x1, k); hy = lerp(y0, y1, k); g.lineTo(hx, hy); break; }\n  }\n  g.strokeStyle = c; g.lineWidth = w; g.lineJoin = 'round'; g.lineCap = 'round'; if (dash) g.setLineDash(dash);\n  if (p > 0) g.stroke(); g.setLineDash([]); g.lineCap = 'butt'; g.lineJoin = 'miter';\n  return [hx, hy];\n}","b13FracAtX":"function b13FracAtX(pts, x) {\n  let tot = 0, at = 0; for (let i = 1; i < pts.length; i++) { const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); if (x >= pts[i][0]) at += d; else if (x > pts[i - 1][0]) at += d * (x - pts[i - 1][0]) / (pts[i][0] - pts[i - 1][0]); tot += d; }\n  return at / tot;\n}","b13YAt":"const b13YAt = (pts, x) => { for (let i = 1; i < pts.length; i++) if (x <= pts[i][0]) return lerp(pts[i - 1][1], pts[i][1], clamp((x - pts[i - 1][0]) / (pts[i][0] - pts[i - 1][0]))); return pts[pts.length - 1][1]; };","b13Quad":"const b13Quad = (a, c, b, n = 28) => Array.from({ length: n + 1 }, (_, i) => { const u = i / n, v = 1 - u; return [v * v * a[0] + 2 * v * u * c[0] + u * u * b[0], v * v * a[1] + 2 * v * u * c[1] + u * u * b[1]]; });","b13Axes":"function b13Axes(g, x0 = 36, x1 = 292, y0 = 34, y1 = 160) {\n  for (let i = 1; i <= 3; i++) ln(g, x0, lerp(y1, y0, i / 3), x1, lerp(y1, y0, i / 3), K.grid, 1, [2, 4]);\n  ln(g, x0, y1, x1, y1, K.mute, 1); ln(g, x0, y0 - 6, x0, y1, K.mute, 1);\n}","b13Band":"function b13Band(g, x0, a0, a1, x1, b0, b1, c, a = .55) {\n  const xm = (x0 + x1) / 2; g.beginPath(); g.moveTo(x0, a0); g.bezierCurveTo(xm, a0, xm, b0, x1, b0); g.lineTo(x1, b1); g.bezierCurveTo(xm, b1, xm, a1, x0, a1); g.closePath();\n  alpha(g, a, () => { g.fillStyle = c; g.fill(); });\n}","b13Tag":"function b13Tag(g, s, x, y, fill, col, w = 40) { rr(g, x - w / 2, y - 9, w, 18, 5, fill); tx(g, s, x, y + .5, { size: 10, f: 'm', w: 600, c: col }); }"};
