  const ring = (id = 'ring', x = 38, y = 26, size = 24) => box(id, 'mc-ring', '', `left:${x}%;top:${y}%;width:${size}%;aspect-ratio:1;height:auto;`);
  const bar = (id, x = 18, y = 48, w = 64, h = 10, cls = '') => box(id, `mc-bar ${cls}`, '', at(x, y, w, h));
  const track = (id, keyframes, extra = {}) => ({ selector: `[data-mc="${id}"]`, keyframes, ...extra });
  const k = (offset, properties) => ({ offset, ...properties });
