  const hide = (id, when) => track(id, [k(0, { opacity: 1 }), k(when, { opacity: 1 }), k(when + .035, { opacity: 0 }), k(1, { opacity: 0 })]);
  const pop = (id, when = .2) => track(id, [k(0, { opacity: 0, transform: 'scale(.65)' }), k(when, { opacity: 0, transform: 'scale(.65)' }), k(when + .07, { opacity: 1, transform: 'scale(1.14)' }), k(when + .15, { opacity: 1, transform: 'scale(1)' }), k(1, { opacity: 1, transform: 'scale(1)' })]);
