  const check = (id = 'check', x = 40, y = 30, w = 20, h = 38) => `<svg class="mc-svg" style="${at(x, y, w, h)}" viewBox="0 0 60 60"><path data-mc="${id}" class="stage-object web-motion-object mc-svg-stroke" d="M10 30 L24 43 L50 15" pathLength="1"/></svg>`;
