  define('modalMorph',scene('mb-modal-scene','<span class="mb-modal-context"><i></i><i></i><i></i><i></i></span>'+item('mb-modal-shade')+item('mb-modal-card','<i></i><b>DETAIL</b><span></span>')+caption('SELECTED CARD → DIALOG')),[track('.mb-modal-shade',fade(.15,.59,0,.7)),track('.mb-modal-card',hold({left:'24px',top:'27px',width:'62px',height:'44px',borderRadius:'6px'},{left:'38px',top:'15px',width:'144px',height:'84px',borderRadius:'12px'},.15,.68)),track('.mb-modal-card b',fade(.35,.63)),track('.mb-modal-card span',fade(.43,.7))],{focus:'왼쪽 작은 카드를 중앙으로 옮기고, 실제 폭·높이를 넓힌다. 배경 암막과 상세 글자를 나중에 동기화시킨다.',focusEn:'Move the small left-hand card to the center and grow its actual width and height, then bring in the dimmed backdrop and detail text in sync.',recipe:'Source rect(24,27,62,44) → dialog rect(38,15,144,84); radius 6→12; backdrop and content follow.'});
  define('spotlightFocus',scene('mb-spotlight-scene','<span class="mb-spotlight-context"><i></i><i></i><i></i></span>'+item('mb-spotlight-shade')+item('mb-spotlight-subject','FOCUS')+item('mb-spotlight-ring')+caption('DIM CONTEXT / PRESERVE FOCUS')),[track('.mb-spotlight-shade',fade(.12,.52,0,.86)),track('.mb-spotlight-subject',hold({filter:'brightness(.7)'},{filter:'brightness(1.15)'},.12,.55)),track('.mb-spotlight-ring',hold({opacity:0,transform:'scale(.8)'},{opacity:1,transform:'scale(1)'},.13,.62))],{focus:'주변 카드를 어둡게 하고, 중앙 대상과 원형 빛만 남겨 초점을 만든다.',focusEn:'Dim the surrounding cards while preserving the central subject and circular light to create focus.',recipe:'Backdrop opacity 0→.86; foreground subject remains above shade; spotlight ring fades in.'});
  define('inkReveal',scene('mb-ink-scene',svg('<defs><mask id="mb-ink-mask"><rect width="220" height="120" fill="black"/>'+[[52,72],[120,35],[171,72],[88,89]].map(([x,y],i)=>`<circle class="stage-object web-motion-object mb-ink-dot mb-ink-${i}" cx="${x}" cy="${y}" r="0" fill="white"/>`).join('')+'</mask></defs><g mask="url(#mb-ink-mask)"><rect x="25" y="18" width="170" height="83" rx="6" fill="#bbd8c9"/><path d="M25 60Q70 10 111 54T195 44V101H25Z" fill="#4c9885"/><text x="110" y="69" text-anchor="middle" font-size="24" font-weight="900" fill="#183e34">INK</text></g>')+caption('MULTIPLE BLOOMS / ONE REVEAL')),[0,1,2,3].map(i=>track(`.mb-ink-${i}`,hold({r:'0px'},{r:'105px'},.1+i*.075,.65+i*.055))),{focus:'4곳에서 퍼지는 마스크가 불규칙하게 합류하며, 고정된 그림의 표시 영역만 넓힘.',focusEn:'Four growing mask regions merge irregularly, expanding only the visible portion of a stationary image.',recipe:'SVG mask with four white circles; varied start times and radius 0→105px; merge into a complete reveal.'});
  define('badgePop',scene('mb-badge-scene','<span class="mb-badge-card"><i>✉</i><b>Inbox</b></span>'+item('mb-badge-count','1')+caption('ONLY THE BADGE MOVES')),[track('.mb-badge-count',[{transform:'scale(0) rotate(-18deg)',opacity:0,offset:0},{transform:'scale(0) rotate(-18deg)',opacity:0,offset:.15},{transform:'scale(1.2) rotate(5deg)',opacity:1,offset:.44},{transform:'scale(.95) rotate(-2deg)',opacity:1,offset:.59},{transform:'scale(1) rotate(0)',opacity:1,offset:.72},{transform:'scale(1) rotate(0)',opacity:1,offset:1}])],{focus:'Inbox의 면과 글자를 완전히 정지시키고 오른쪽 위 배지만 확대·반동.',focusEn:'Keep the Inbox surface and label completely still while only the corner badge pops and settles.',recipe:'Static parent; badge scale 0→1.2→.95→1 with rotation −18→5→−2→0.'});
  define('colorPulse',scene('mb-color-scene',item('mb-color-subject','STATUS')+caption('HUE + LIGHT / NO TRANSFORM')),[track('.mb-color-subject',[{background:'#294c68',borderColor:'#6499bd',color:'#c4deed',offset:0},{background:'#294c68',borderColor:'#6499bd',color:'#c4deed',offset:.12},{background:'#337b60',borderColor:'#a6efd0',color:'#e4fff3',offset:.45},{background:'#294c68',borderColor:'#6499bd',color:'#c4deed',offset:.8},{background:'#294c68',borderColor:'#6499bd',color:'#c4deed',offset:1}])],{focus:'위치나 크기를 전혀 움직이지 않고, 파랑에서 초록으로 색상과 밝기를 바꿨다가 원래 색으로 되돌린다.',focusEn:'Keep position and size fixed, pulse hue and brightness from blue to green, then restore the original colors.',recipe:'background #294c68→#337b60→#294c68; synchronize border/text colors; no transform.'});
  define('optimisticUpdate',scene('mb-optimistic-scene',item('mb-optimistic-row','<i></i><b>Publish change</b>')+item('mb-optimistic-pending','PENDING…')+item('mb-optimistic-done','✓ CONFIRMED')+caption('INSTANT LOCAL UPDATE → SERVER CONFIRM')),[track('.mb-optimistic-row',[{background:'#1c2d42',borderColor:'#476078',offset:0},{background:'#294a40',borderColor:'#578c74',offset:.1},{background:'#294a40',borderColor:'#578c74',offset:.6},{background:'#1c5545',borderColor:'#83c9a8',offset:.72},{background:'#1c5545',borderColor:'#83c9a8',offset:1}]),track('.mb-optimistic-pending',[{opacity:0,offset:0},{opacity:1,offset:.1},{opacity:1,offset:.59},{opacity:0,offset:.67},{opacity:0,offset:1}]),track('.mb-optimistic-done',fade(.67,.75))],{focus:'조작 직후 행을 임시 갱신 색으로 바꾸고 PENDING 을 표시. 통신 확정에 해당하는 간격 뒤에만 CONFIRMED 로 바꾼다.',focusEn:'Apply a provisional row state immediately and show PENDING; reveal CONFIRMED only after a simulated response delay.',recipe:'Local update at 10%; pending until 60%; confirmation at 75%; production must also handle rollback.'});
