   "css": ".mark {\n  background: linear-gradient(transparent 60%, #ffe46b 60%) no-repeat 0 0 / 0% 100%;\n  box-decoration-break: clone; -webkit-box-decoration-break: clone;\n  transition: background-size 1.2s cubic-bezier(.65,0,.35,1) .5s;\n}\n.mark.is-in { background-size: 100% 100%; }   /* IntersectionObserver로 부여 */\n@media (prefers-reduced-motion: reduce) { .mark { transition:none; } }",
   "motion": "import { animate, inView } from 'motion';\ninView('.mark', (el) => {\n  animate(el, { backgroundSize: ['0% 100%', '100% 100%'] }, { duration: 1.2, delay: .5, ease: 'easeInOut' });\n});",
   "svg": "// 손그림풍(rough-notation)\nimport { annotate } from 'rough-notation';\nconst a = annotate(document.querySelector('.mark'), {\n  type: 'highlight', color: 'rgba(255,228,107,.6)', animationDuration: 1200, multiline: true\n});\na.show();"
