  "recipes": {
   "motion": "import { animate, stagger } from 'motion';\nanimate('.blur-text span',\n  { filter: ['blur(10px)', 'blur(5px)', 'blur(0px)'], opacity: [0, .5, 1], y: [-50, 5, 0] },\n  { duration: .7, times: [0, .5, 1], ease: 'easeOut', delay: stagger(0.2) });",
   "waapi": "document.querySelectorAll('.blur-text span').forEach((el, i) => el.animate([\n  { filter: 'blur(10px)', opacity: 0, transform: 'translateY(-50px)' },\n  { filter: 'blur(5px)', opacity: .5, transform: 'translateY(5px)' },\n  { filter: 'blur(0)', opacity: 1, transform: 'none' }\n], { duration: 700, delay: i * 200, easing: 'ease-out', fill: 'both' }));",
   "css": ".blur-text span { display: inline-block; animation: drop .7s ease-out both; animation-delay: calc(var(--i) * .2s); }\n@keyframes drop {\n  0% { filter: blur(10px); opacity: 0; transform: translateY(-50px); }\n  50% { filter: blur(5px); opacity: .5; transform: translateY(5px); }\n}\n@media (prefers-reduced-motion: reduce) { .blur-text span { animation: none; } }"
  },
