  "recipes": {
   "motion": "import { useScroll, useVelocity, useSpring, useTransform, useMotionTemplate, motion } from 'motion/react';\nconst { scrollY } = useScroll();\nconst v = useSpring(useVelocity(scrollY), { stiffness: 200, damping: 30 });\nconst speed = useTransform(v, [-2000, 0, 2000], [1, 0, 1]);           // 속도(방향은 무시)\nconst wdth = useTransform(speed, [0, 1], [75, 125]);\nconst slnt = useTransform(speed, [0, 1], [0, -12]);\nconst fvs = useMotionTemplate`'wdth' ${wdth}, 'slnt' ${slnt}`;\nreturn <motion.h1 style={{ fontVariationSettings: fvs }}>{text}</motion.h1>;",
   "gsap": "const setW = gsap.quickTo('.speed', '--wdth', { duration: .8, ease: 'power3' });\nconst setS = gsap.quickTo('.speed', '--slnt', { duration: .8, ease: 'power3' });\nScrollTrigger.create({ onUpdate: self => {\n  const s = gsap.utils.clamp(0, 1, Math.abs(self.getVelocity()) / 2000);\n  setW(75 + 50 * s); setS(-12 * s);\n} });\n/* .speed { font-variation-settings: 'wdth' var(--wdth), 'slnt' var(--slnt); } */"
  },
  "sources": [
   "https://developer.mozilla.org/en-US/docs/Web/CSS/font-variation-settings",
   "https://gsap.com/docs/v3/Plugins/ScrollTrigger/"
  ],
