  "recipes": {
   "gsap": "// .window-text { background: url(trip.jpg) center / cover; -webkit-background-clip: text; background-clip: text; color: transparent; }\ngsap.timeline({ scrollTrigger: { trigger: '.zoom-section', pin: true, scrub: true, start: 'top top', end: '+=200%' } })\n  .to('.window-text', { scale: 40, transformOrigin: '47% 55%', ease: 'power2.in' })   // 글자의 굵은 부분을 원점으로\n  .to('.full-image', { opacity: 1, ease: 'none', duration: .15 }, '>-0.15');",
   "svg": "<svg viewBox=\"0 0 800 450\" role=\"img\" aria-label=\"TRAVEL\">\n  <defs><mask id=\"m\"><rect width=\"100%\" height=\"100%\" fill=\"black\"/>\n    <text id=\"word\" x=\"400\" y=\"290\" text-anchor=\"middle\" font-size=\"220\" font-weight=\"900\" fill=\"white\">TRAVEL</text>\n  </mask></defs>\n  <image href=\"trip.jpg\" width=\"800\" height=\"450\" preserveAspectRatio=\"xMidYMid slice\" mask=\"url(#m)\"/>\n</svg>\n<!-- #word의 transform: scale()을 스크롤에 연동 -->",
   "css": "@supports (animation-timeline: scroll()) {\n  .window-text { animation: zoom linear both; animation-timeline: scroll(root); animation-range: 0 150vh; transform-origin: 47% 55%; }\n  @keyframes zoom { to { transform: scale(40); } }\n}"
  },
