  "recipes": {
   "motion": "import { animate, hover } from 'motion';\nimport { splitText } from 'motion-plus';\nconst { words } = splitText(document.querySelector('.lift'));\nhover(words, el => {\n  animate(el, { y: -6, color: 'var(--accent)' }, { type: 'spring', stiffness: 400, damping: 26 });\n  return () => animate(el, { y: 0, color: 'var(--ink)' }, { type: 'spring', stiffness: 400, damping: 26 });\n});",
   "css": "/* 단어별로 <span class=\"w\">한국어는 공백 기준 어절 단위로 나눈다 */\n.lift .w { display: inline-block; transition: translate .25s cubic-bezier(.34,1.56,.64,1), color .2s; }\n.lift .w:hover { translate: 0 -6px; color: var(--accent); }\n@media (prefers-reduced-motion: reduce) { .lift .w { transition: color .2s; } .lift .w:hover { translate: none; } }"
  },
