function ln(g, x1, y1, x2, y2, c, w = 1.5, dash) { g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.strokeStyle = c; g.lineWidth = w; if (dash) g.setLineDash(dash); g.stroke(); if (dash) g.setLineDash([]); }
function tx(g, s, x, y, o = {}) { s = L(s); const fw = (o.f === 'd') ? 800 : (o.w || 700); g.font = `${fw} ${o.size || 16}px ${FONT[o.f || 'b']}`; g.textAlign = o.a || 'center'; g.textBaseline = o.bl || 'middle'; g.fillStyle = o.c || K.ink; g.fillText(s, x, y); }
function alpha(g, a, fn) { const p = g.globalAlpha; g.globalAlpha = p * clamp(a); fn(); g.globalAlpha = p; }
function xf(g, x, y, sx, sy, rot, fn) { g.save(); g.translate(x, y); if (rot) g.rotate(rot); g.scale(sx, sy); fn(); g.restore(); }
function clip(g, x, y, w, h, fn) { g.save(); g.beginPath(); g.rect(x, y, w, h); g.clip(); fn(); g.restore(); }
function floor(g, y = 168) { ln(g, 24, y, W - 24, y, K.mute, 1); }
function label(g, s, x = 12, y = 14) { tx(g, s, x, y, { a: 'left', size: 10, w: 500, f: 'm', c: K.mute }); }
function star(g, x, y, r1, r2, n, fill, rot = 0) { g.beginPath(); for (let i = 0; i < n * 2; i++) { const a = rot + i * Math.PI / n - Math.PI / 2, r = i % 2 ? r2 : r1; g.lineTo(x + Math.cos(a) * r, y + Math.sin(a) * r); } g.closePath(); g.fillStyle = fill; g.fill(); }
function poly(g, pts, fill, stroke, lw = 1.5) { g.beginPath(); pts.forEach(([x, y], i) => i ? g.lineTo(x, y) : g.moveTo(x, y)); g.closePath(); if (fill) { g.fillStyle = fill; g.fill(); } if (stroke) { g.strokeStyle = stroke; g.lineWidth = lw; g.stroke(); } }
// 형태의 윤곽을 N점으로 맞춘다(모프용)
function shapePts(kind, cx, cy, r, n = 64) { const out = []; for (let i = 0; i < n; i++) { const a = i / n * TAU - Math.PI / 2; let rr2 = r;
    if (kind === 'square') { const c = Math.cos(a), s = Math.sin(a); rr2 = r / Math.max(Math.abs(c), Math.abs(s)); }
    else if (kind === 'star') { const k = (i / n * 10) % 2; rr2 = r * (k < 1 ? lerp(1, .45, k) : lerp(.45, 1, k - 1)); }
    else if (kind === 'tri') { const seg3 = Math.PI * 2 / 3, aa = ((a + Math.PI / 2) % seg3 + seg3) % seg3 - seg3 / 2; rr2 = r * .5 / Math.cos(aa); }
    else if (kind === 'heart') { const tt = i / n * TAU; out.push([cx + r * .06 * 16 * Math.sin(tt) ** 3, cy - r * .06 * (13 * Math.cos(tt) - 5 * Math.cos(2 * tt) - 2 * Math.cos(3 * tt) - Math.cos(4 * tt))]); continue; }
    out.push([cx + Math.cos(a) * rr2, cy + Math.sin(a) * rr2]); } return out; }
const lerpPts = (a, b, t) => a.map((p, i) => [lerp(p[0], b[i][0], t), lerp(p[1], b[i][1], t)]);
// UI용 작은 커서
function cursor(g, x, y, press = 0) { xf(g, x, y, 1 - press * .15, 1 - press * .15, 0, () => { poly(g, [[0, 0], [0, 15], [4, 11], [7, 17], [9.5, 16], [6.5, 10], [11, 10]], K.ink, K.paper, 1.2); }); }

// ===== 텍스트용 도구 =====
// 데모는 f(g, t, o). o = { text, lang, font, sampleKo, sampleEn, samplesKo, samplesEn }
//   text   … 사용자가 입력한 문자(비어 있으면 견본)
//   lang   … 'ko' | 'en'(견본 언어)
//   font   … 'sans' | 'serif' | 'mono'(서체 전환)
// 글자 위치는 measureText로 측정. 결합 문자·이모지는 Intl.Segmenter로 1글자로 취급.

const FONTS = {
  sans: { d: 'Pretendard,system-ui,sans-serif', w: 800 },
  serif: { d: '"Nanum Myeongjo","Noto Serif KR","Batang",serif', w: 700 },
  mono: { d: 'ui-monospace,SFMono-Regular,Menlo,Consolas,monospace', w: 600 }
};
const CJK = /[　-ヿ㐀-鿿豈-﫿＀-￯]/;
const isCJK = s => CJK.test(s);

// 표시할 문자열(입력이 있으면 그것, 없으면 샘플)
function TXT(o, ko, en) {
  if (o && o.text && o.text.trim()) return o.text.trim().split(/\s*[\/\n]\s*/)[0];
  const lang = (o && o.lang) || 'ko';
  if (lang === 'en') return en != null ? en : (o && o.sampleEn) || 'MOTION';
  return ko != null ? ko : (o && o.sampleKo) || '모션';
}
// 복수의 단어·문장이 필요한 데모용. 입력은 '/' 또는 줄바꿈으로 구분. 부족한 부분은 샘플로 보충.
function TXTS(o, ko = [], en = []) {
  const lang = (o && o.lang) || 'ko';
  const base = lang === 'en' ? (en.length ? en : (o && o.samplesEn) || []) : (ko.length ? ko : (o && o.samplesKo) || []);
  if (o && o.text && o.text.trim()) {
    const parts = o.text.trim().split(/\s*[\/\n]\s*/).filter(Boolean);
    if (parts.length >= base.length || !base.length) return parts;
    return parts.concat(base.slice(parts.length));
  }
  return base.slice();
}
// 서체
function FAM(o, kind = 'd') {
  if (kind === 'm') return FONTS.mono.d;
  return (FONTS[(o && o.font) || 'sans'] || FONTS.sans).d;
}
function WGT(o, w) { return w != null ? w : (FONTS[(o && o.font) || 'sans'] || FONTS.sans).w; }
function setFont(g, size, weight = 800, family = FONTS.sans.d) { g.font = `${weight} ${size}px ${family}`; }

// 문자소(보이는 1글자)로 나눈다
const _seg = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter(undefined, { granularity: 'grapheme' }) : null;
function graphemes(s) { return _seg ? Array.from(_seg.segment(s), x => x.segment) : Array.from(s); }
// 단어로 나눔. 영어는 공백, 일본어는 Intl.Segmenter의 word(어절에 가까운 단위)로 구분.
const _wseg = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter('ja', { granularity: 'word' }) : null;
function words(s) {
  if (!isCJK(s)) return s.split(/(\s+)/).filter(x => x.length);
  if (!_wseg) return graphemes(s);
  // 조사·기호를 앞 단어에 붙여 어절다운 묶음으로 만듦
  const out = [];
  for (const x of _wseg.segment(s)) {
    const w = x.segment;
    const glue = !x.isWordLike || /^[ぁ-ゖー、。！？」』）]+$/.test(w) && w.length <= 3;
    if (glue && out.length && !/\s/.test(w)) out[out.length - 1] += w; else out.push(w);
  }
  return out;
}

// 글자를 나열해 위치를 측정.
//   반환값: { glyphs:[{ch,x,y,w,i,wi,li,n}], words:[{text,x,w,li,i0,i1}], lines:[...], size, width, height, top, font }
//   x … 그 글자의 중심, y … 베이스라인
function layout(g, text, opt = {}) {
  const o = opt.o || {};
  const family = opt.family || FAM(o, opt.kind || 'd');
  const weight = opt.weight != null ? opt.weight : WGT(o);
  const cx = opt.x != null ? opt.x : W / 2, cy = opt.y != null ? opt.y : H / 2;
  const maxW = opt.maxW || 280, maxLines = opt.maxLines || 2, lh = opt.lh || 1.22, align = opt.align || 'center';
  const spacing = opt.spacing || 0; // em 단위 자간
  let size = opt.size || 44;
  const minSize = opt.minSize || 10;
  const wordsArr = words(text);
  const measure = s => { setFont(g, size, weight, family); return g.measureText(s).width; };
  let lines;
  for (let guard = 0; guard < 40; guard++) {
    setFont(g, size, weight, family);
    const sp = spacing * size;
    const wlen = w => graphemes(w).reduce((a, c) => a + g.measureText(c).width + sp, 0);
    lines = []; let cur = [], cw = 0;
    for (const w of wordsArr) {
      const ww = wlen(w);
      if (cur.length && cw + ww > maxW && !/^\s+$/.test(w)) { lines.push(cur); cur = []; cw = 0; if (/^\s+$/.test(w)) continue; }
      if (!cur.length && /^\s+$/.test(w)) continue;
      cur.push(w); cw += ww;
    }
    if (cur.length) lines.push(cur);
    const widest = Math.max(...lines.map(l => l.reduce((a, w) => a + wlen(w), 0)));
    if ((lines.length <= maxLines && widest <= maxW) || size <= minSize) break;
    size = Math.max(minSize, size * .9);
  }
  setFont(g, size, weight, family);
  const sp = spacing * size;
  const lineH = size * lh, total = lineH * lines.length;
  const glyphs = [], wordList = [], lineList = [];
  let gi = 0, wi = 0;
  lines.forEach((ln, li) => {
    // 행 끝의 공백은 제외
    while (ln.length && /^\s+$/.test(ln[ln.length - 1])) ln.pop();
    const chars = ln.flatMap(w => graphemes(w));
    const widths = chars.map(c => g.measureText(c).width + sp);
    const lw = widths.reduce((a, b) => a + b, 0) - (chars.length ? sp : 0);
    let x = align === 'left' ? cx : align === 'right' ? cx - lw : cx - lw / 2;
    const y = cy - total / 2 + lineH * (li + .5) + size * .36;
    const l0 = gi;
    let k = 0;
    ln.forEach(w => {
      const gs = graphemes(w), i0 = gi, x0 = x;
      gs.forEach(c => { const cw = widths[k++]; glyphs.push({ ch: c, x: x + (cw - sp) / 2, y, w: cw - sp, i: gi, wi, li, space: /^\s$/.test(c) }); x += cw; gi++; });
      wordList.push({ text: w, x: (x0 + x - sp) / 2, w: x - x0 - sp, li, i0, i1: gi - 1, i: wi, space: /^\s+$/.test(w) });
      wi++;
    });
    lineList.push({ x: align === 'left' ? cx + lw / 2 : align === 'right' ? cx - lw / 2 : cx, y, w: lw, i0: l0, i1: gi - 1, i: li });
  });
  glyphs.forEach(gl => gl.n = glyphs.length);
  const realWords = wordList.filter(w => !w.space);
  realWords.forEach((w, k) => { w.k = k; w.nk = realWords.length; for (let i = w.i0; i <= w.i1; i++) { glyphs[i].wk = k; } });
  return { glyphs, words: wordList, realWords, lines: lineList, size, width: Math.max(0, ...lineList.map(l => l.w)), height: total, top: cy - total / 2, family, weight, spacing: sp, lineH };
}

// 글자 하나 그리기. s = { dx, dy, sx, sy, rot, skx, a, c, stroke, lw, blur, ax, ay, fill:false }
//   ax, ay … 회전·확대의 기준(글자 중심에서의 비율. ay=1이면 베이스라인 부근)
function glyph(g, gl, L, s = {}) {
  if (gl.space) return;
  const a = s.a == null ? 1 : s.a;
  if (a <= .001) return;
  const size = s.size || L.size;
  g.save();
  g.globalAlpha *= clamp(a);
  const px = gl.x + (s.dx || 0), py = gl.y - size * .36 + (s.dy || 0);
  const ax = (s.ax || 0) * gl.w / 2, ay = (s.ay || 0) * size * .5;
  g.translate(px + ax, py + ay);
  if (s.rot) g.rotate(s.rot);
  if (s.skx) g.transform(1, 0, Math.tan(s.skx), 1, 0, 0);
  g.scale(s.sx == null ? 1 : s.sx, s.sy == null ? (s.sx == null ? 1 : s.sx) : s.sy);
  g.translate(-ax, -ay);
  setFont(g, size, s.weight || L.weight, s.family || L.family);
  g.textAlign = 'center'; g.textBaseline = 'middle';
  if (s.blur > .3) softBlur(g, s.blur);
  if (s.stroke) { g.lineWidth = s.lw || 1.5; g.strokeStyle = s.stroke; g.lineJoin = 'round'; g.strokeText(gl.ch, 0, 0); }
  if (s.fill !== false) { g.fillStyle = s.c || K.ink; g.fillText(gl.ch, 0, 0); }
  g.restore();
}
// 한꺼번에 그리기(fn이 글자별 스타일을 반환. null이면 그리지 않음)
function glyphs(g, L, fn) { L.glyphs.forEach(gl => { if (gl.space) return; const s = fn ? fn(gl) : {}; if (s) glyph(g, gl, L, s); }); }
// 한 줄 통째로(자간 유지한 채) 보통으로 그리기
function plain(g, L, c = K.ink, a = 1) { glyphs(g, L, () => ({ c, a })); }

// 흐림: filter를 쓸 수 있는 환경에서는 그것을, 못하는 환경(일부 Safari)에서는 아무것도 하지 않음
const FILTER_OK = (() => { try { const c = document.createElement('canvas').getContext('2d'); c.filter = 'blur(2px)'; return c.filter === 'blur(2px)'; } catch (e) { return false; } })();
function softBlur(g, px) { if (FILTER_OK && px > .3) g.filter = `blur(${px.toFixed(2)}px)`; }

// 시간차(스태거)
//   order(i, n, from) … 0..1의 순서. from: 'start' | 'end' | 'center' | 'edges' | 'random'
function order(i, n, from = 'start', seed = 7) {
  if (n <= 1) return 0;
  if (from === 'end') return (n - 1 - i) / (n - 1);
  if (from === 'center') return Math.abs(i - (n - 1) / 2) / ((n - 1) / 2);
  if (from === 'edges') return 1 - Math.abs(i - (n - 1) / 2) / ((n - 1) / 2);
  if (from === 'random') { const r = rng(seed); const keys = Array.from({ length: n }, () => r()); const sorted = keys.slice().sort((a, b) => a - b); return sorted.indexOf(keys[i]) / (n - 1); }
  return i / (n - 1);
}
// i번째 진행도(0..1). t0에서 시작해 각 요소는 each초씩 늦고 dur초에 0→1.
function stag(t, i, n, t0 = .3, each = .04, dur = .5, ease = E.outExpo, from = 'start') {
  const d = order(i, n, from) * each * (n - 1);
  return ease(clamp((t - t0 - d) / dur));
}
// 전체 길이를 정한 뒤 배분하는 판(total초 안에 전원이 들어감)
function spread(t, i, n, t0, total, dur, ease = E.outExpo, from = 'start') {
  const each = n > 1 ? Math.max(0, total - dur) / (n - 1) : 0;
  return stag(t, i, n, t0, each, dur, ease, from);
}

// After Effects의 레인지 셀렉터(Range Selector)
//   p … 오프셋(-1 → 1로 끝에서 끝까지 통과), shape: square | rampUp | rampDown | triangle | round | smooth
//   반환값 0..1 = 그 글자에 걸리는 양
function rangeSel(i, n, p, shape = 'square', ease = 0) {
  const u = n <= 1 ? .5 : (i + .5) / n;      // 글자 위치 0..1
  const x = u - p;                             // 선택 범위 안에서의 위치(0..1 범위가 선택)
  let v;
  switch (shape) {
    case 'rampUp': v = clamp(1 - x); v = x < 0 ? 1 : x > 1 ? 0 : 1 - x; break;
    case 'rampDown': v = x < 0 ? 0 : x > 1 ? 1 : x; break;
    case 'triangle': v = x < 0 || x > 1 ? 0 : 1 - Math.abs(x * 2 - 1); break;
    case 'round': v = x < 0 || x > 1 ? 0 : Math.sqrt(1 - (x * 2 - 1) ** 2); break;
    case 'smooth': v = x < 0 || x > 1 ? 0 : .5 - .5 * Math.cos(x * TAU); break;
    default: v = x >= 0 && x <= 1 ? 1 : 0;
  }
  if (ease) v = lerp(v, E.smooth(v), ease);
  return clamp(v);
}

// 글자를 다른 레이어에 그려 합성(글자 모양 마스크 등에 사용)
const _layers = [];
function layer(g, fn, k = 0) {
  const c = g.canvas; if (!c) { fn(g); return; }
  let L = _layers[k];
  if (!L) { L = _layers[k] = document.createElement('canvas'); }
  if (L.width !== c.width || L.height !== c.height) { L.width = c.width; L.height = c.height; }
  const lg = L.getContext('2d');
  // 마스크용 캔버스를 재사용해도 앞 컷의 그림자·클립·문자 설정을 물려받지 않음.
  if (typeof lg.reset === 'function') lg.reset();
  else L.width = L.width;
  lg.setTransform(1, 0, 0, 1, 0, 0); lg.globalAlpha = 1; lg.globalCompositeOperation = 'source-over'; lg.filter = 'none'; lg.clearRect(0, 0, L.width, L.height);
  lg.setTransform(g.getTransform());
  fn(lg);
  g.save(); g.setTransform(1, 0, 0, 1, 0, 0); g.drawImage(L, 0, 0); g.restore();
}
// 글자 모양 안에만 fill을 그림(글자 마스크)
function textMask(g, drawText, drawFill) {
  layer(g, lg => { drawText(lg); lg.globalCompositeOperation = 'source-in'; drawFill(lg); lg.globalCompositeOperation = 'source-over'; });
}

// 세로쓰기: 오른쪽 열부터 왼쪽으로. 반환값의 glyph는 x,y(글자 중심)에 배치. 문장부호는 오른쪽 위로 붙임.
function vlayout(g, text, opt = {}) {
  const o = opt.o || {};
  const family = opt.family || FAM(o), weight = opt.weight != null ? opt.weight : WGT(o);
  let size = opt.size || 30; const maxH = opt.maxH || 150, colGap = opt.colGap || 1.5;
  const chars = graphemes(text).filter(c => c !== '\n');
  const perCol = Math.max(1, Math.floor(maxH / (size * 1.05)));
  const cols = Math.ceil(chars.length / perCol);
  const cx = opt.x != null ? opt.x : W / 2, cy = opt.y != null ? opt.y : H / 2;
  const totalW = (cols - 1) * size * colGap;
  const out = chars.map((ch, i) => {
    const col = Math.floor(i / perCol), row = i % perCol, rows = Math.min(perCol, chars.length - col * perCol);
    const x = cx + totalW / 2 - col * size * colGap, y = cy - (Math.min(perCol, chars.length) - 1) * size * 1.05 / 2 + row * size * 1.05;
    const punct = /[、。，．]/.test(ch), rot = /[ー〜～—\-]/.test(ch);
    return { ch, x: x + (punct ? size * .32 : 0), y: y + size * .36 - (punct ? size * .32 : 0), w: size, i, li: col, n: chars.length, vrot: rot };
  });
  return { glyphs: out, size, family, weight, lines: [], words: [], cols };
}
// 세로쓰기 1글자(장음 등은 90° 회전)
function vglyph(g, gl, L, s = {}) { glyph(g, gl, L, Object.assign({}, s, { rot: (s.rot || 0) + (gl.vrot ? Math.PI / 2 : 0) })); }

// 문자열 폭
function textW(g, s, size, weight = 800, family = FONTS.sans.d) { setFont(g, size, weight, family); return g.measureText(s).width; }
// 딱 맞는 크기
function fitSize(g, s, maxW, size, weight = 800, family = FONTS.sans.d) { const w = textW(g, s, size, weight, family); return w > maxW ? size * maxW / w : size; }
// 경로에 글자를 놓음. path(u) → [x, y](u = 0..1). 반환값은 각 글자의 [x, y, 각도]
function onPath(g, text, path, size, opt = {}) {
  const family = opt.family || FONTS.sans.d, weight = opt.weight || 800, start = opt.start || 0, spacing = opt.spacing || 0;
  const N = 400, pts = [], acc = [0];
  for (let k = 0; k <= N; k++) pts.push(path(k / N));
  for (let k = 1; k <= N; k++) acc.push(acc[k - 1] + Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]));
  const total = acc[N];
  const at = d => { d = clamp(d, 0, total); let lo = 0, hi = N; while (hi - lo > 1) { const m = (lo + hi) >> 1; if (acc[m] < d) lo = m; else hi = m; } const f = (d - acc[lo]) / ((acc[hi] - acc[lo]) || 1); const x = lerp(pts[lo][0], pts[hi][0], f), y = lerp(pts[lo][1], pts[hi][1], f); return [x, y, Math.atan2(pts[hi][1] - pts[lo][1], pts[hi][0] - pts[lo][0])]; };
  setFont(g, size, weight, family);
  let d = start * total;
  return graphemes(text).map((ch, i) => { const w = g.measureText(ch).width; const p = at(d + w / 2); d += w + spacing * size; return { ch, x: p[0], y: p[1], ang: p[2], w, i, len: total }; });
}

