    const cxq = Lt.lines.reduce((a,l)=>a+l.x,0)/Lt.lines.length, hw = Lt.width/2, x0 = cxq-hw-8, x1 = cxq+hw+10, ym = Lt.top+Lt.height/2+2;
    const p1 = seg(t, .3, 1.3, E.outQuad), p2 = seg(t, 1.42, 2.3, E.outQuad), out = seg(t, 2.3, 2.55, E.inOut);
    if (p1 > 0) alpha(g, 1-out, () => {
      const d1 = crDense([[x0, ym-2.5], [x0+(x1-x0)*.5, ym-2.5], [x1, ym-2.5]], 1.6, 33);
      crGrain(g, d1, p1*d1.length, CR_PAL.yellow, 19, crPr.high, .12);
      if (p2 > 0) { const d2 = crDense([[x0, ym+2.5], [x0+(x1-x0)*.5, ym+2.5], [x1, ym+2.5]], 1.6, 37); crGrain(g, d2, p2*d2.length, CR_PAL.yellow, 19, crPr.high, .12); }
    });
    label(g, '크레파스 형광펜 · 2번 덧칠');
