  values: ['넘어짐 300–400ms', '깜빡임 2회	간격 150ms', '간격 150ms', '팀명은 고정'], valuesEn: ['flip 300–400ms', '2 flashes', '150ms interval', 'team names stay fixed'],
  duration: 350, easing: 'ease-in-out', feel: ['경쾌함', '단단함'], use: ['영상', '게임', 'UI'],
